INSERT INTO `master_merek` VALUES (1, 'Tugu Buaya', 'tugu-buaya', 'images/uploads/brand/tugu-buaya_1774403899.png', 'Bercita rasa kuat serta tekstur tegas. Dikembangkan sejak 1977, Tugu Buaya memiliki rasa yang unik dengan karakter kopi yang diterima semua orang.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:58:19');
INSERT INTO `master_merek` VALUES (2, 'Uang Emas', 'uang-emas', 'images/uploads/brand/uang-emas_1774403882.png', 'Dibuat dari biji kopi pilihan, cobalah kopi asli dengan paduan metode pengolahan tradisional dan modern ini. Dari kreasi kopi hitam yang sesungguhnya, temukan nuansa kontemporer yang tiada duanya.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:58:02');
INSERT INTO `master_merek` VALUES (3, 'Rasa Sayang', 'rasa-sayang', 'images/uploads/brand/rasa-sayang_1774403865.png', 'Rasa sayang eh, Rasa sayang sayang eh ~ Diracik pada 1984 dengan rasa dan aroma nostalgia, Rasa sayang membawa penghormatan bagi kopi di masa lalu, sekaligus memupuk rasa nostalgia yang semakin hangat dengan teknik presisi yang lebih baru.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:57:45');
INSERT INTO `master_merek` VALUES (4, 'HaoCafe', 'hao-cafe', 'images/uploads/brand/hao-cafe_1774585550.png', 'Kopi yang dibuat secara sempurna dengan tekstur kuat yang mengeluarkan aroma khas dan rasa yang mantap.', NULL, 'active', '2026-03-17 15:07:41', '2026-04-10 13:53:08');
INSERT INTO `master_merek` VALUES (5, 'Jaheku', 'jaheku', 'images/uploads/brand/jaheku_1774403821.png', 'Jaheku / definisi / “Jahe kesukaanku” dalam bahasa Indonesia. Merupakan bahan pangan yang familiar di banyak negara, Jaheku menyajikan segala manfaat dan kesegaran jahe kepada konsumen dalam bentuk minuman, dengan kombinasi rasa Jaheku Gula Aren, dan juga Jaheku Madu, memantapkan berbagai manfaat serta rasa unik jahe yang selalu disukai.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:57:01');
INSERT INTO `master_merek` VALUES (6, 'BROCHOCO', 'brochoco', 'images/uploads/brand/brochoco_1774403800.png', 'Mau minuman coklat dengan berbagai rasa pilihan? BROCHOCO jawabannya! Isi hari-harimu dengan BROCHOCO, dengan rasa Original juga Choco Banana. Nikmati beragam rasa manisnya coklat dan lembutnya krim, berpadu seimbang dalam cita rasa yang menggoda. Favorit semua kalangan dan selalu jadi pilihan, dengan berbagai kreasi penyajian yang lezat.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:56:40');
INSERT INTO `master_merek` VALUES (7, 'UCAFÉ', 'ucafe', 'images/uploads/brand/ucafe_1774403779.png', 'UCAFÉ for “U”. Dirancang untuk menyatukan dunia peminum kopi dari berbagai latar, dengan ragam rasa dan aromanya, UCAFÉ terdepan menemani dirimu yang sesungguhnya, menjaga cita-cita, impian, dan juga kesukaanmu.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:56:19');
INSERT INTO `master_merek` VALUES (8, 'Supresso', 'supresso', 'images/uploads/brand/supresso_1773886613.png', 'Dengan biji-biji kopi yang berasal dari timur hingga barat Indonesia, koleksi kopi single-origin Supresso menghasilkan profil rasa yang premium, mewah sekaligus unik. Dengan sepenuh hati, kami fokus menyajikan kopi kualitas tinggi untuk penikmat kopi di seluruh dunia dalam bentuk biji, bubuk, drip, dan kapsul. Nikmati pengalaman kopi Indonesia dalam kualitas dan kemurniannya, bersama Supresso.', 'With coffee beans sourced from east to west Indonesia, Supresso\'s single-origin coffee collection delivers premium, luxurious, and unique flavor profiles. We wholeheartedly focus on serving high-quality coffee to coffee lovers worldwide in bean, ground, drip, and capsule forms. Experience Indonesian coffee in its purest form with Supresso.', 'active', '2026-03-17 15:07:41', '2026-04-08 13:39:33');
INSERT INTO `master_merek` VALUES (9, 'BaliCafé', 'balicafe', 'images/uploads/brand/balicafe_1774403760.png', 'Diracik dari kopi Bali asli, nikmati hasil kreasi Balicafé kami, dan menyatulah dengan tradisi kopi pulau Bali yang magis.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:56:00');
INSERT INTO `master_merek` VALUES (10, 'Mesin', 'mesin', 'images/uploads/brand/mesin_1774404402.jpg', 'Mesin-mesin & peralatan khusus yang dirancang untuk menyajikan kualitas terbaik bagi setiap cangkir kopi Anda.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 09:06:42');
INSERT INTO `master_merek` VALUES (11, 'intiRasa', 'intirasa', 'images/uploads/brand/intirasa_1774403708.png', 'Santan bubuk intiRasa merupakan versi praktis dari cita rasa gurih ala santan kelapa yang sesungguhnya, berkualitas dan disesuaikan dengan kebutuhan dapur anda yang serba cepat.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-25 08:55:08');
INSERT INTO `master_merek` VALUES (12, 'Others', 'others', NULL, 'Koleksi produk lainnya dari Indraco.', NULL, 'active', '2026-03-17 15:07:41', '2026-03-17 15:07:41');
INSERT INTO `master_merek` VALUES (13, 'Kopi Ceria', 'kopi-ceria', 'images/uploads/brand/1782967880_logo-kopi-ceria-baru.png', NULL, NULL, 'active', '2026-07-02 04:51:20', '2026-07-02 04:51:20');
INSERT INTO `master_news` VALUES (1, 'peluncuran-supresso-speciality-series', 'Peluncuran Supresso Speciality Series', 'Launch of Supresso Speciality Series', 'February 20, 2026', 'February 20, 2026', 'Supresso memperkenalkan koleksi kopi pilihan nusantara dengan profil sangrai khusus yang menonjolkan karakter keotentikan rasa khas daerah asal biji kopi Sumatra, Java, Bali, dan Toraja.', 'Supresso introduces selected Indonesian coffee collections with specialized roast profiles highlighting authentic origin flavor notes from Sumatra, Java, Bali, and Toraja beans.', 'images/news/news-8.jpg', '2026-07-31 03:03:30', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (2, 'komitmen-indraco-keberlanjutan-petani-kopi', 'Komitmen INDRACO Dalam Program Keberlanjutan Petani Kopi Indonesia', 'INDRACO Commitment to Sustainability Programs for Indonesian Coffee Farmers', '28 Juni 2026', '28 June 2026', 'Melalui program Corporate Social Responsibility (CSR), INDRACO memberikan pendampingan dan kemitraan berkelanjutan kepada ratusan petani kopi lokal guna meningkatkan produktivitas serta kualitas panen kopi nasional.', 'Through its Corporate Social Responsibility (CSR) program, INDRACO provides sustainable assistance and partnership to hundreds of local coffee farmers to increase national coffee harvest productivity and quality.', 'images/uploads/news/news-csr-farmers.jpg', '2026-07-31 03:03:30', '2026-07-31 03:03:30');
INSERT INTO `master_news` VALUES (3, 'balicreamer-formulasi-baru-krimer-nabati-premium', 'Balicreamer Hadirkan Formulasi Baru Krimer Nabati Premium Lebih Creamy', 'Balicreamer Introduces New Richer & Creamier Non-Dairy Creamer Formulation', '10 Juli 2026', '10 July 2026', 'Balicreamer meluncurkan formulasi krimer nabati terbaru yang lebih larut dan menghasilkan tekstur lembut creamy sempurna untuk racikan kopi, teh, dan minuman kekinian.', 'Balicreamer launches its newest non-dairy creamer formulation that dissolves easily and creates a rich, smooth creamy texture perfect for coffee, tea, and modern beverage recipes.', 'images/uploads/news/news-balicreamer.jpg', '2026-07-31 03:03:30', '2026-07-31 03:03:30');
INSERT INTO `master_news` VALUES (4, 'event-heritage-asli-kabupaten-pasuruan', 'Event Heritage Asli Kabupaten Pasuruan', 'Heritage Event Asli Kabupaten Pasuruan', 'May 20, 2026', 'May 20, 2026', 'Pasuruan memiliki kekayaan budaya dan sejarah yang luar biasa. INDRACO berpartisipasi aktif dalam mendukung kegiatan Heritage Asli Kabupaten Pasuruan untuk mempromosikan warisan budaya lokal serta mempererat hubungan dengan masyarakat sekitar.', 'Pasuruan has an extraordinary cultural and historical heritage. INDRACO actively participates in supporting the Original Heritage event of Pasuruan Regency to promote local cultural heritage and strengthen bonds with the community.', 'images/news/news-1.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (5, 'komitmen-indraco-untuk-wellbeing-karyawan', 'Komitmen Indraco untuk Wellbeing Karyawan', 'Indraco Commitment for Employee Wellbeing', 'May 10, 2026', 'May 10, 2026', 'Kesejahteraan dan kesehatan karyawan merupakan prioritas utama INDRACO. Berbagai program kebugaran, pemeriksaan kesehatan berkala, fasilitas kerja yang nyaman, dan dukungan lingkungan kerja terpadu terus dihadirkan demi menciptakan tim yang produktif dan bahagia.', 'Employee wellbeing and health are top priorities at INDRACO. Various fitness programs, regular health checkups, comfortable working facilities, and integrated work environment support are continuously provided to create a happy, productive team.', 'images/news/news-2.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (6, 'produk-baru-dari-kopi-tugu-buaya', 'Produk Baru dari Kopi Tugu Buaya', 'New Product Launch from Kopi Tugu Buaya', 'April 28, 2026', 'April 28, 2026', 'Kopi Tugu Buaya secara resmi meluncurkan varian produk kemasan baru dengan penawaran menarik beli 1 gratis 1 piring dan gelas eksklusif. Varian ini memberikan cita rasa kopi mantap nan legendaris khas Jawa Timur.', 'Kopi Tugu Buaya officially launches a new packaged product variant with exciting buy 1 get 1 free plate and exclusive glass offers. This variant delivers the bold and legendary coffee taste signature of East Java.', 'images/news/news-3.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (7, 'keikutsertaan-indraco-di-pameran-internasional', 'Keikutsertaan Indraco di Pameran Internasional', 'Indraco Participation in International Exhibition', 'April 15, 2026', 'April 15, 2026', 'INDRACO kembali memamerkan jajaran produk olahan kopi, krimer, dan minuman berkualitas internasional pada ajang pameran dagang internasional. Langkah ini merupakan bagian dari ekspansi pasar global perusahaan.', 'INDRACO once again exhibits its lineup of coffee, non-dairy creamer, and beverage products of international quality at the international trade exhibition. This step is part of the company\'s global market expansion.', 'images/news/news-4.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (8, 'program-donasi-indraco-peduli-lingkungan', 'Program Donasi Indraco Peduli Lingkungan', 'Indraco Environmental Care Donation Program', 'April 02, 2026', 'April 02, 2026', 'Sebagai bentuk kepedulian terhadap kelestarian alam dan lingkungan hidup, INDRACO menyelenggarakan program penanaman pohon dan aksi donasi peduli lingkungan bersama komunitas lokal di sekitar area operasional pabrik.', 'As part of our commitment to environmental sustainability, INDRACO organizes tree planting programs and environmental care donations alongside local communities around our factory operational area.', 'images/news/news-5.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (9, 'pelatihan-barista-bersama-kopi-supresso', 'Pelatihan Barista Bersama Kopi Supresso', 'Barista Training with Supresso Coffee', 'March 18, 2026', 'March 18, 2026', 'Supresso mengadakan sesi pelatihan barista profesional bagi para peracik kopi muda dan pencinta kopi speciality untuk mengasah keahlian teknik manual brew, ekstraksi espresso, dan pembuatan latte art presisi.', 'Supresso hosts professional barista training sessions for young coffee artisans and speciality coffee enthusiasts to hone manual brewing techniques, espresso extraction, and precision latte art creation.', 'images/news/news-6.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (10, 'indraco-meraih-penghargaan-fmcg-terbaik-2026', 'Indraco Meraih Penghargaan FMCG Terbaik 2026', 'Indraco Wins Best FMCG Award 2026', 'March 05, 2026', 'March 05, 2026', 'Atas komitmen tinggi terhadap konsistensi mutu produk dan inovasi bisnis FMCG berkelanjutan, INDRACO dianugerahi penghargaan prestisius sebagai salah satu perusahaan FMCG terbaik tahun 2026.', 'Due to high commitment to product quality consistency and sustainable FMCG business innovation, INDRACO was awarded the prestigious title of one of the best FMCG companies of 2026.', 'images/news/news-7.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_news` VALUES (11, 'inovasi-krimer-nabati-balicreamer-lebih-creamy', 'Inovasi Krimer Nabati Balicreamer Lebih Creamy', 'Richer & Creamier Balicreamer Non-Dairy Creamer Innovation', 'February 01, 2026', 'February 01, 2026', 'Balicreamer meluncurkan formulasi krimer nabati premium terbaru yang lebih cepat larut dan menghasilkan tekstur lembut creamy sempurna untuk racikan kopi, teh hangat, dan kreasi minuman modern.', 'Balicreamer launches its newest premium non-dairy creamer formulation that dissolves instantly and yields a silky, creamy texture perfect for coffee, hot tea, and modern beverage recipes.', 'images/news/news-9.jpg', '2026-07-31 03:14:39', '2026-07-31 03:14:39');
INSERT INTO `master_produk` VALUES (1, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs30', 'TBS30', 'Kenikmatan Kopi TUGU BUAYA adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan biji kopi pilihan, inovasi pengolahan, dan pengepakan yang baik, menghasilkan Kopi TUGU BUAYA. Sebuah karya seni minum kopi bagi Anda pecinta kopi.', 'Tugu Buaya Kopi Special<br><br>Kenikmatan Tugu Buaya Kopi Special adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan biji kopi pilihan, inovasi pengolahan, dan pengepakan yang baik, menghasilkan Tugu Buaya Kopi Special. Sebuah karya seni minum kopi bagi Anda pecinta kopi.', 'Renceng', '10 sachets x 30g', 44800.00, 'images/uploads/1774412900_p_tugu-buaya-kopi-special-tbs30.png', '[\"TUGUBUAYA/TB-302.webp\"]', 0, '2025-01-13 11:28:04', NULL, 'Tugu-Buaya-Kopi-Special-10-sachets-x-30g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:38:45');
INSERT INTO `master_produk` VALUES (2, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs7', 'TBS7', '<br><br>', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok kopi Tugu Buaya ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap dinikmati.', 'Renceng', '10 sachets x 7g', 12600.00, 'images/uploads/1774412604_p_tugu-buaya-kopi-special-tbs7.png', '[\"TUGUBUAYA/TB-7_2.webp\", \"TUGUBUAYA/TB-7_3.webp\"]', 0, '2025-01-13 11:28:26', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-10-sachets-x-7g', 'Tugu-Buaya-Kopi-Special-10-sachets-x-7g', 'https://shopee.co.id/product/283021328/6042626786/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-10-sachets-x-7g/ps--INT-60044-00121', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:48:40');
INSERT INTO `master_produk` VALUES (3, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbt600', 'TBT600', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok kopi Tugu Buaya ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap dinikmati.', 'Tuper', '1 Tuper x 600g', 90900.00, 'images/uploads/1774410773_p_tugu-buaya-kopi-special-tbt600.png', '[\"TUGUBUAYA/TBTUPER6002.webp\", \"TUGUBUAYA/TBTUPER6003.webp\"]', 0, '2025-01-13 11:27:36', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-1-Tuper-x-600g', 'Tugu-Buaya-Kopi-Special-1-Tuper-x-600g', 'https://shopee.co.id/product/283021328/6142630899/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-tuper-600g/ps--INT-60044-00120', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:49:19');
INSERT INTO `master_produk` VALUES (4, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbt1000', 'TBT1000', '<br><br>', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok kopi Tugu Buaya ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap dinikmati.', 'Tuper', '1 Tuper x 1000g', 148800.00, 'images/uploads/1774412557_p_tugu-buaya-kopi-special-tbt1000.png', '[\"TUGUBUAYA/TBTUPER1KG2.webp\", \"TUGUBUAYA/TBTUPER1KG3.webp\"]', 0, '2025-01-13 11:27:11', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-1-Tuper-x-1000g', 'Tugu-Buaya-Kopi-Special-1-Tuper-x-1000g', 'https://shopee.co.id/product/283021328/4642632655/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-tuper-1kg/ps--INT-60044-00119', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:49:51');
INSERT INTO `master_produk` VALUES (5, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Mocca', 'tugu-buaya-kopi-mocca-tbm27', 'TBM27', '<br><br>', 'Tugu Buaya Kopi Mocca<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian <br>Tuangkan kopi dari dalam sachet ke dalam gelas dan tambahkan 175ml air mendidih ke dalamnya. Aduk sampai rata dan siap untuk Anda nikmati.', 'Renceng', '10 sachets x 27g', 18600.00, 'images/uploads/1774412839_p_tugu-buaya-kopi-mocca-tbm27.png', '[\"TUGUBUAYA/TB_SPEC_MOKA2.webp\", \"TUGUBUAYA/TB_SPEC_MOKA3.webp\"]', 0, '2024-11-05 10:19:20', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Mocca-10-sachets-x-27g', 'Tugu-Buaya-Kopi-Mocca-10-sachets-x-27g', 'https://shopee.co.id/product/283021328/3642728092/', 'https://www.blibli.com/p/tugu-buaya-mocca-10-sachets-x-27g/ps--INT-60044-00118', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:50:37');
INSERT INTO `master_produk` VALUES (6, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Jahe', 'tugu-buaya-kopi-jahe-tbj25', 'TBJ25', '<br><br>', 'Tugu Buaya Kopi Jahe<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian <br>Tuangkan satu bungkus TUGU BUAYA Kopi Jahe ke dalam cangkir. Seduh dengan air mendidih ±175ml. Aduklah hingga merata. TUGU BUAYA Kopi Jahe siap dihidangkan.', 'Renceng', '10 sachets x 25g', 17300.00, 'images/uploads/1774412803_p_tugu-buaya-kopi-jahe-tbj25.png', '[\"TUGUBUAYA/TB_SPEC_JAHE3_3.webp\", \"TUGUBUAYA/TB_SPEC_JAHE3_1.webp\"]', 0, '2024-11-05 10:08:41', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Jahe-10-sachets-x-25g', 'Tugu-Buaya-Kopi-Jahe-10-sachets-x-25g', 'https://shopee.co.id/product/283021328/5842625543/', 'https://www.blibli.com/p/tugu-buaya-kopi-jahe-10-sachets-x-25g/ps--INT-60044-00117', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:51:17');
INSERT INTO `master_produk` VALUES (7, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi+Susu', 'tugu-buaya-kopisusu-tbsu27', 'TBSU27', '<br><br>', 'Tugu Buaya Kopi Susu<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian <br>Tuangkan kopi dari dalam sachet ke dalam gelas dan tambahkan 175ml air mendidih ke dalamnya. Aduk sampai rata dan siap untuk Anda nikmati.', 'Renceng', '10 sachets x 27g', 18900.00, 'images/uploads/1774412766_p_tugu-buaya-kopisusu-tbsu27.png', '[\"TUGUBUAYA/TB_SPEC_SUSU2.webp\", \"TUGUBUAYA/TB_SPEC_SUSU3.webp\"]', 0, '2024-11-05 10:18:33', 'https://indracostore.com/product/Tugu-Buaya-Kopi+Susu-10-sachets-x-27g', 'Tugu-Buaya-Kopi+Susu-10-sachets-x-27g', 'https://shopee.co.id/product/283021328/7042625281/', 'https://www.blibli.com/p/tugu-buaya-kopi-susu-10-sachets-x-27g/ps--INT-60044-00116', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:52:57');
INSERT INTO `master_produk` VALUES (8, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi+Gula', 'tugu-buaya-kopigula-tbg18', 'TBG18', '<br><br>', 'Tugu Buaya Kopi Gula<br><br>Perpaduan kopi dengan gula dalam komposisi yang tepat. Menghasilkan kopi gula yang harum, sedap dan nikmat.<br><br>\r\nSaran Penyajian<br>Tuangkan satu bungkus Tugu Buaya Kopi Gula ke dalam gelas, tambahkan ±200ml  air panas, aduk dan sajikan.', 'Renceng', '10 sachets x 18g', 8900.00, 'images/uploads/1774412713_p_tugu-buaya-kopigula-tbg18.png', '[\"TUGUBUAYA/TB_KOPI_GULA2.webp\", \"TUGUBUAYA/TB_KOPI_GULA3.webp\"]', 0, '2024-11-05 10:07:52', 'https://indracostore.com/product/Tugu-Buaya-Kopi+Gula-10-sachets-x-18g', 'Tugu-Buaya-Kopi+Gula-10-sachets-x-18g', 'https://shopee.co.id/product/283021328/3742721024/', 'https://www.blibli.com/p/tugu-buaya-kopi-gula-10-sachets-x-18g/ps--INT-60044-00114', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:53:33');
INSERT INTO `master_produk` VALUES (9, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi+Gula Special Mix', 'tugu-buaya-kopigula-special-mix-tbg25', 'TBG25', '<br><br>', 'Tugu Buaya Kopi Gula Special Mix<br><br>Perpaduan kopi dengan gula dalam komposisi yang tepat. Menghasilkan kopi gula yang harus, sedap dan nikmat.<br><br>\r\nSaran Penyajian<br>Tuangkan satu bungkus Tugu Buaya Kopi Gula ke dalam gelas, tambahkan  ±200ml air panas, aduk rata dan kopi siap dinikmati.', 'Renceng', '10 sachets x 25g', 17700.00, 'images/uploads/1774412643_p_tugu-buaya-kopigula-special-mix-tbg25.png', '[\"TUGUBUAYA/TB_SPEC_MIX_GULA2.webp\", \"TUGUBUAYA/TB_SPEC_MIX_GULA3.webp\"]', 0, '2024-11-05 10:16:14', 'https://indracostore.com/product/Tugu-Buaya-Kopi+Gula-Special-Mix-10-sachets-x-25g', 'Tugu-Buaya-Kopi+Gula-Special-Mix-10-sachets-x-25g', 'https://shopee.co.id/product/283021328/4942629803/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-mix-kopi-gula-10-sachets-x-25g/ps--INT-60044-00115', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:54:48');
INSERT INTO `master_produk` VALUES (10, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tb12', 'TB12', 'Tugu Buaya Kopi Special<br><br>Kenikmatan Tugu Buaya Kopi Special adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan biji kopi pilihan, inovasi pengolahan, dan pengepakan yang baik, menghasilkan Tugu Buaya Kopi Special. Sebuah karya seni minum kopi bagi Anda pecinta kopi.', 'Tugu Buaya Kopi Special<br><br>Kenikmatan Tugu Buaya Kopi Special adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan biji kopi pilihan, inovasi pengolahan, dan pengepakan yang baik, menghasilkan Tugu Buaya Kopi Special. Sebuah karya seni minum kopi bagi Anda pecinta kopi.', 'Renceng', '10 sachets x 12g', 7100.00, 'images/uploads/1774410869_p_tugu-buaya-kopi-special-tb12.png', '[\"TUGUBUAYA/TB-122.webp\"]', 0, '2023-12-07 01:46:08', NULL, 'Tugu-Buaya-Kopi-Special-10-sachets-x-12g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:38:50');
INSERT INTO `master_produk` VALUES (11, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs450-1', 'TBS450', '', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Bag', '1 Bag x 450g', 30800.00, 'images/uploads/1774412287_p_tugu-buaya-kopi-special-tbs450-1.png', NULL, 1, NULL, NULL, 'Tugu-Buaya-Kopi-Special-1-Bag-x-450g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:38:50');
INSERT INTO `master_produk` VALUES (12, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs60', 'TBS60', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok kopi Tugu Buaya ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap dinikmati.', 'Renceng', '10 sachets x 60g', 87700.00, 'images/uploads/1774412506_p_tugu-buaya-kopi-special-tbs60.png', '[\"TUGUBUAYA/TB-SPECIAL-60g-BACK.webp\", \"TUGUBUAYA/TB-SPECIAL-60g.webp\"]', 0, '2025-01-13 11:26:18', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-10-sachets-x-60g', 'Tugu-Buaya-Kopi-Special-10-sachets-x-60g', 'https://shopee.co.id/product/283021328/5642622183/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-10-sachets-x-60g/ps--INT-60044-00112', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:46:00');
