INSERT INTO `master_produk` VALUES (21, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi+Susu', 'rasa-sayang-kopisusu-rss30', 'RSS30', 'Kenikmatan kopi Rasa Sayang adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan pilihan biji kopi yang terbaik hingga proses pengolahan dan pengemasan yang higienis di bawah pengawasan yang ketat. Sebuah karya seni minum kopi bagi Anda pecinta kopi. Selamat menikmati!', 'Rasa Sayang Kopi Susu dimulai dengan pilihan biji kopi terbaik, perpaduan gula murni dan susu serta diolah dengan mesin paling modern untuk menghasilkan rasa dan aroma yang tepat bagi pecinta kopi.<br><br>\r\nSaran Penyajian:<br>Tuang satu bungkus Rasa Sayang Kopi Susu ke dalam cangkir. Seduh dengan air mendidih ±175ml. Aduklah hingga merata. Rasa Sayang Kopi Susu siap dihidangkan.', 'Renceng', '10 sachets x 25g', 18600.00, 'images/uploads/1774411719_p_Rasa-Sayang-Kopi-Susu-Renceng-(10 sachets x 25g).png', '[\"RASASAYANG/RS_SUSU_2.webp\", \"RASASAYANG/RS_SUSU_3.webp\"]', 0, '2024-11-05 10:35:30', 'https://indracostore.com/product/Rasa-Sayang-Kopi+Susu-10-sachets-x-25g', 'Rasa-Sayang-Kopi+Susu-10-sachets-x-25g', 'https://shopee.co.id/product/283021328/7042612312/', 'https://www.blibli.com/p/rasa-sayang-kopi-susu-10-sachets-x-25g/ps--INT-60044-00129', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:13:36');
INSERT INTO `master_produk` VALUES (22, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi Gold Special', 'rasa-sayang-kopi-gold-special-rsg65', 'RSG65', '<br><br>', 'Rasa Sayang Kopi Gold Special<br><br>Kenikmatan kopi Rasa Sayang adalah hasil dari perjalanan panjang sebuah proses pencarian rasa dan aroma kopi yang tepat bagi pecinta kopi. Dimulai dengan pilihan biji kopi yang terbaik hingga proses pengolahan dan pengemasan yang higienis di bawah pengawasan yang ketat. Sebuah karya seni minum kopi bagi Anda pecinta kopi. Selamat menikmati!<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok makan kopi Rasa Sayang ke dalam cangkir dan tambahkan gula secukupnya sesuai selera Anda. Tuangkan air panas ±200ml. Aduklah hingga merata. Kopi Rasa Sayang siap dihidangkan.', 'Renceng', '10 sachets x 65g', 102600.00, 'images/uploads/1774411688_p_Rasa-Sayang-Kopi-Gold-Special-Renceng-(10 sachets x 65g).png', '[\"RASASAYANG/RS-GOLD-65-2.webp\", \"RASASAYANG/RS-GOLD-65-3.webp\"]', 0, '2024-09-03 10:35:55', 'https://indracostore.com/product/Rasa-Sayang-Kopi-Gold-Special-10-sachets-x-65g', 'Rasa-Sayang-Kopi-Gold-Special-10-sachets-x-65g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:14:15');
