INSERT INTO `master_produk` VALUES (26, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi Jahe', 'rasa-sayang-kopi-jahe-rsj23', 'RSJ23', '<br><br>', 'Rasa Sayang Kopi Jahe lahir dari perjalanan panjang akan pencarian rasa tradisional kopi jahe Indonesia. Diproduksi dengan kontrol kualitas yang ketat dan dengan bangga kmai mempersembahkan kopi jahe dengan rasa dan aroma yang pas bagi para pecinta kopi.\r\n<br><br>\r\nSaran Penyajian:<br>Tuangkan satu sachet Rasa Sayang Kopi Jahe ke dalam cangkir, tambahkan 150ml air panas dan aduk hingga merata. Rasa Sayang Kopi Jahe siap dihidangkan.', 'Renceng', '10 sachets x 23g', 16600.00, 'images/uploads/1774411594_p_Rasa-Sayang-Kopi-Jahe-Renceng-(10 sachets x 23g).png', '[\"RASASAYANG/RSJAHE2.webp\", \"RASASAYANG/RSJAHE3.webp\"]', 0, '2024-11-05 10:23:49', 'https://indracostore.com/product/Rasa-Sayang-Kopi-Jahe-10-sachets-x-23g', 'Rasa-Sayang-Kopi-Jahe-10-sachets-x-23g', 'https://shopee.co.id/product/283021328/3242777616/', 'https://www.blibli.com/p/rasa-sayang-kopi-jahe-10-sachets-x-23g/ps--INT-60044-00130', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:17:05');
