INSERT INTO `master_produk` VALUES (38, 5, 11, NULL, NULL, NULL, 'Jaheku Jahe Madu', 'jaheku-jahe-madu-jk002', 'JK002', 'Perpaduan jahe dengan madu atau jahe dengan gula aren dalam komposisi yang tepat, menghasilkan minuman Jaheku yang harum, sedap dan nikmat.', 'Jaheku Jahe Madu<br><br>Perpaduan jahe dengan madu dalam komposisi yang tepat, menghasilkan minuman Jaheku yang harum, sedap dan nikmat.\r\n<br><br>\r\nSaran Penyajian:<br>Tuangkan satu bungkus Jaheku ke dalam gelas, tambahkan 150ml air panas, aduk rata dan siap dinikmati.', 'Renceng', '10 sachets x 20g', 12000.00, 'images/uploads/1774411064_p_jaheku-jahe-madu-jk002.webp', '[\"JAHEKU/JAHEKU_(MADU)_copy3.webp\"]', 0, '2024-11-18 11:02:11', 'https://indracostore.com/product/Jaheku-Jahe-Madu-10-sachets-x-20g', 'Jaheku-Jahe-Madu-10-sachets-x-20g', 'https://shopee.co.id/product/283021328/5542920217/', 'https://www.blibli.com/p/jaheku-jahe-madu-r10-10-sachets-x-20g/ps--INT-60044-00137', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:30:36');
INSERT INTO `master_produk` VALUES (39, 5, 11, NULL, NULL, NULL, 'Jaheku Jahe Gula Aren', 'jaheku-jahe-gula-aren-jk001', 'JK001', '<br><br>', 'Jaheku Jahe Gula Aren<br><br>Perpaduan jahe dengan gula aren dalam komposisi yang tepat, menghasilkan minuman Jaheku yang harum, sedap dan nikmat.<br><br>\r\nSaran Penyajian:<br>Tuangkan satu bungkus Jaheku ke dalam gelas, tambahkan 150ml air panas, aduk rata dan siap dinikmati.', 'Renceng', '10 sachets x 20g', 12000.00, 'images/uploads/1774411014_p_jaheku-jahe-gula-aren-jk001.webp', '[\"JAHEKU/JAHEKU-GULA AREN-20g-BACK.webp\", \"JAHEKU/JAHEKU_(AREN)_copy3.webp\"]', 0, '2024-11-18 11:01:54', 'https://indracostore.com/product/Jaheku-Jahe-Gula-Aren-10-sachets-x-20g', 'Jaheku-Jahe-Gula-Aren-10-sachets-x-20g', 'https://shopee.co.id/product/283021328/5042921657/', 'https://www.blibli.com/p/jaheku-jahe-gula-aren-r10-10-sachets-x-20g/ps--INT-60044-00136', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:30:56');
INSERT INTO `master_produk` VALUES (40, 6, 10, NULL, NULL, NULL, 'BROCHOCO Banana', 'brochoco-banana-bc002', 'BC002', 'Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO. Rasakan nikmatnya cokelat khas yang berpadu dengan krim lembut.', 'BROCHOCO Banana<br><br>Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO Banana. Rasakan nikmatnya cokelat pisang khas yang berpadu dengan krim lembut.\r\n<br><br>\r\nSaran Penyajian: Tuangkan BROCHOCO Banana ke dalam cangkir. Tambahkan 150ml air panas, aduk rata dan siap dihidangkan.', 'Renceng', '10 sachets x 25g', 16700.00, 'images/uploads/1774410704_p_brochoco-banana-bc002.png', '[\"BROCHOCO/Brococo-banana3.webp\"]', 0, '2024-11-05 11:02:57', 'https://indracostore.com/product/BROCHOCO-Banana-10-sachets-x-25g', 'BROCHOCO-Banana-10-sachets-x-25g', 'https://shopee.co.id/product/283021328/7942915288/', 'https://www.blibli.com/p/brochoco-banana-r10-chocolate-drink-minuman-coklat-10-sachets-x-25g/ps--INT-60044-00140', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:53:29');
