INSERT INTO `master_produk` VALUES (48, 2, 9, NULL, NULL, NULL, 'Uang Emas Kopi Special', 'uang-emas-kopi-special-ues1000', 'UES1000', '<br><br>', 'Uang Emas Kopi Special<br><br>Kami mengolah Uang Emas Kopi Special dari biji kopi pilihan. Melalui kontrol kualitas yang ketat dan proses pengemasan yg higienis menghasilkan kopi dengan kenikmatan tiada tara.\r\n<br><br>\r\nSaran Penyajian:<br>Masukkan satu sachet kopi ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap untuk dinikmati.', 'Bag', '1 Bag x 1000g', 75200.00, 'images/uploads/1774410299_p_uang-emas-kopi-special-ues1000.webp', '[\"UANGEMAS/UE_1000_2.webp\", \"UANGEMAS/UE_1000_3.webp\"]', 0, '2025-01-13 11:25:51', 'https://indracostore.com/product/Uang-Emas-Kopi-Special-1-Bag-x-1000g', 'Uang-Emas-Kopi-Special-1-Bag-x-1000g', 'https://shopee.co.id/product/283021328/9531003424/', 'https://www.blibli.com/p/uang-emas-kopi-special-1kg/ps--INT-60044-00110', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:05:41');
INSERT INTO `master_produk` VALUES (49, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi SQ', 'rasa-sayang-kopi-sq-rssq60', 'RSSQ60', '<br><br>', 'Kopi bubuk Rasa Sayang \"Super Quality\" dibuat dari biji kopi pilihan dan diolah dengan mesin modern sehingga menghasilkan kopi yang sedap , harum, dan nikmat rasanya.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok makan kopi Rasa Sayang \"Super Quality\" ke dalam cangkir dan tambahkan gula secukupnya sesuai selera Anda. Tuangkan air panas ±200ml. Aduklah hingga merata. Kopi Rasa Sayang \"Super Quality\" siap dihidangkan.', 'Renceng', '10 sachets x 60g', 79400.00, 'images/uploads/1774411514_p_Rasa-Sayang-Kopi-SQ-Renceng-(10 sachets x 60).png', '[\"RASASAYANG/RS_SQ_60_Beli_1_Renteng_2_Gelas_Tangkai1.webp\", \"RASASAYANG/RS_SQ_60_Beli_1_Renteng_2_Gelas_Tangkai2.webp\", \"RASASAYANG/RS_SQ_-_3.webp\"]', 0, '2024-11-05 10:55:23', 'https://indracostore.com/product/Rasa-Sayang-Kopi-SQ-10-sachets-x-60g', 'Rasa-Sayang-Kopi-SQ-10-sachets-x-60g', 'https://shopee.co.id/product/283021328/9391786572/', 'https://www.blibli.com/p/rasa-sayang-kopi-sq-10-sachets-x-60g/ps--INT-60044-00135', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:24:18');
INSERT INTO `master_produk` VALUES (50, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi Bali', 'rasa-sayang-kopi-bali-rsb40', 'RSB40', '<br><br>', 'Terbuat dari biji kopi Bali pilihan, sehingga tercipta rasa kopi yang nikmat dan cita rasa yang gurih dipadu dengan aroma khas Bali. Semua itu tersaji pada Rasa Sayang Kopi Bali.<br><br>\r\nSaran Penyajian:<br>Tuangkan Kopi Rasa Sayang Bali dengan gula secukupnya. Tambahkan air panas kedalam cangkir/gelas. Aduk rata, Kopi Rasa Sayang Bali siap dinikmati', 'Renceng', '10 sachets x 40g', 25000.00, 'images/uploads/1774411491_p_Rasa-Sayang-Kopi-Bali-Renceng-(10 sachets x 40g).png', '[\"RASASAYANG/RS_BALI_40g3.webp\"]', 0, '2024-01-15 16:00:11', '', 'Rasa-Sayang-Kopi-Bali-10-sachets-x-40g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:05');
