INSERT INTO `master_produk` VALUES (56, 7, 6, NULL, NULL, NULL, 'UCAFÉ Pure Coffee Special P20', 'ucaf-pure-coffee-special-p20-ucsp20', 'UCSP20', 'Tradisi kopi asli Indonesia berlanjut dan semakin baru, UCAFE Pure Coffee Special. 100% kopi murni dengan rasa asli yang pas untuk keseharianmu yang produktif, bersemangat dan melangkah maju.<br><br>Temukan Kemurnian Kopi.', 'Tradisi kopi asli Indonesia berlanjut dan semakin baru, UCAFÉ Pure Coffee Special. 100% kopi murni dengan rasa asli yang pas untuk keseharianmu yang produktif, bersemangat dan melangkah maju.<br><br>Temukan Kemurnian Kopi.', 'Bag', '20 sachets x 7g', 20200.00, 'images/uploads/1774424544_p_ucaf-pure-coffee-special-p20-ucsp20.png', '[\"UCAFE/UCAFESPECIAL 140.webp\", \"UCAFE/UCAFE_SPECIAL_140.webp\"]', 0, '2024-11-05 11:23:06', 'https://indracostore.com/product/UCAF%C3%89-Pure-Coffee-Special-P20-20-sachets-x-7g', 'UCAFÉ-Pure-Coffee-Special-P20-20-sachets-x-7g', 'https://shopee.co.id/product/283021328/19305007924/', 'https://www.blibli.com/p/ucafe-pure-coffee-special-p20-7g-x-20-sachets/ps--INT-60044-00089', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:42:24');
INSERT INTO `master_produk` VALUES (57, 7, 6, NULL, NULL, NULL, 'UCAFÉ Pure Coffee Special', 'ucaf-pure-coffee-special-ucs150', 'UCS150', 'Tradisi kopi asli Indonesia berlanjut dan semakin baru, UCAFÉ Pure Coffee Special. 100% kopi murni dengan rasa asli yang pas untuk keseharianmu yang produktif, bersemangat dan melangkah maju.<br><br>Temukan Kemurnian Kopi.', 'Tradisi kopi asli Indonesia berlanjut dan semakin baru, UCAFÉ Pure Coffee Special. 100% kopi murni dengan rasa asli yang pas untuk keseharianmu yang produktif, bersemangat dan melangkah maju.<br><br>Temukan Kemurnian Kopi.', 'Bag', '1 Bag x 150g', 20900.00, 'images/uploads/1774424529_p_ucaf-pure-coffee-special-ucs150.png', '[\"UCAFE/ucafe_special_150_slide23.webp\", \"UCAFE/ucafe_special_150_slide24.webp\"]', 0, '2024-11-05 11:21:49', 'https://indracostore.com/product/UCAF%C3%89-Pure-Coffee-Special-1-Bag-x-150g', 'UCAFÉ-Pure-Coffee-Special-1-Bag-x-150g', 'https://shopee.co.id/product/283021328/18605009303/', 'https://www.blibli.com/p/ucafe-pure-coffee-special-150gr/ps--INT-60044-00088', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:42:09');
INSERT INTO `master_produk` VALUES (58, 6, 10, NULL, NULL, NULL, 'BROCHOCO Original', 'brochoco-original-bc003', 'BC003', 'BROCHOCO Original<br><br>Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO Original. Rasakan nikmatnya cokelat khas yang berpadu dengan krim lembut.', 'BROCHOCO Original<br><br>Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO Original. Rasakan nikmatnya cokelat khas yang berpadu dengan krim lembut.\r\n<br><br>\r\nSaran Penyajian: Tuangkan BROCHOCO Original ke dalam cangkir. Tambahkan 150ml air panas, aduk rata dan siap dihidangkan.', 'Bag', '20 sachets x 25g', 33100.00, 'images/uploads/1774410749_p_brochoco-original-bc003.webp', '[\"BROCHOCO/BROCHOCO_(ORIGINAL)_copy_2@10x-1001.webp\", \"BROCHOCO/BROCHOCO_(ORIGINAL)_copy_2@10x-1003.webp\"]', 0, '2024-11-05 11:17:20', 'https://indracostore.com/product/BROCHOCO-Original-20-sachets-x-25g', 'BROCHOCO-Original-20-sachets-x-25g', 'https://shopee.co.id/product/283021328/19109986199/', 'https://www.blibli.com/p/brochoco-original-p20-chocolate-drink-minuman-coklat-20-sachets-x-25g/ps--INT-60044-00142', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:52:40');
INSERT INTO `master_produk` VALUES (59, 6, 10, NULL, NULL, NULL, 'BROCHOCO Banana', 'brochoco-banana-bc004', 'BC004', 'BROCHOCO Banana<br><br>Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO Banana. Rasakan nikmatnya cokelat pisang khas yang berpadu dengan krim lembut.', 'BROCHOCO Banana<br><br>Nikmati pengalaman rasa yang menyenangkan dalam secangkir BROCHOCO Banana. Rasakan nikmatnya cokelat pisang khas yang berpadu dengan krim lembut.\r\n<br><br>\r\nSaran Penyajian: Tuangkan BROCHOCO Original ke dalam cangkir. Tambahkan 150ml air panas, aduk rata dan siap dihidangkan.', 'Bag', '20 sachets x 25g', 33100.00, 'images/uploads/1774410676_p_brochoco-banana-bc004.webp', '[\"BROCHOCO/BROCHOCO_(BANANA)_copy_2@10x-1001.webp\", \"BROCHOCO/BROCHOCO_(BANANA)_copy_2@10x-1003.webp\"]', 0, '2024-11-05 11:03:29', 'https://indracostore.com/product/BROCHOCO-Banana-20-sachets-x-25g', 'BROCHOCO-Banana-20-sachets-x-25g', 'https://shopee.co.id/product/283021328/17673796514/', 'https://www.blibli.com/p/brochoco-banana-p20-chocolate-drink-minuman-coklat-20-sachets-x-25g/ps--INT-60044-00143', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:52:12');
INSERT INTO `master_produk` VALUES (60, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special 12g B30', 'tugu-buaya-kopi-special-12g-b30-tbb12', 'TBB12', '<br><br>', 'Tugu Buaya Kopi Special 12g B30<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sendok kopi Tugu Buaya ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap dinikmati.', 'Bag', '150 sachets x 12g', 259000.00, 'images/uploads/1774410647_p_tugu-buaya-kopi-special-12g-b30-tbb12.png', '[\"TUGUBUAYA/TB_PAPAN_BALL_11.webp\", \"TUGUBUAYA/TB_PAPAN_BALL_12.webp\", \"TUGUBUAYA/TB_PAPAN_BALL_13.webp\"]', 0, '2025-01-13 11:29:14', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-12g-B30-150-sachets-x-12g', 'Tugu-Buaya-Kopi-Special-12g-B30-150-sachets-x-12g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:43:08');
