INSERT INTO `master_produk` VALUES (86, 8, 4, NULL, NULL, NULL, 'Supresso Java Value Set (Coffee Beans)', 'supresso-java-value-set-coffee-beans-20004', '20004', '', 'Want to know the taste of Java? Its all in this bundle, which brings together: Java and West Java. Each variety contains two distinct flavours - \"West Java\" represents a heavier body while \"Java\" is uniquely malty, sweet and has a slightly lighter body.', 'Can', '2 Can x 200g', 121600.00, 'images/uploads/1774414070_p_supresso-java-value-set-coffee-beans-20004.jpg', '[\"SUPRESSO/Java-Bundle-coffee-beans-2.webp\", \"SUPRESSO/Java-Bundle-coffee-beans-3.webp\", \"SUPRESSO/Java-Bundle-coffee-beans-4.webp\"]', 1, '', '', 'Supresso-Java-Value-Set-(Coffee-Beans)-2-Can-x-200g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:28');
INSERT INTO `master_produk` VALUES (87, 8, 4, NULL, NULL, NULL, 'Supresso Luwak Prestige Collection', 'supresso-luwak-prestige-collection-sup002b', 'SUP002B', 'Introducing to you our Luwak Prestige Collection Bundle, hands down our best-selling product.', 'Introducing to you our Luwak Prestige Collection Bundle, hands down our best-selling product. Endowed from its unique process: herbal scents, chocolaty caramel alongside velvety sweetness envelopes each sip, and finishes with a smooth aftertaste. It is truly an experience like none other in the world of Indonesian Coffee.', 'Can', '1 Set x 210g', 573800.00, 'images/uploads/1774422606_p_supresso-luwak-prestige-collection-sup002b.webp', '[\"SUPRESSO/tc_lwk_02.webp\", \"SUPRESSO/tc_lwk_03.webp\", \"SUPRESSO/tc_lwk_04.webp\"]', 0, '2025-10-08 10:31:15', NULL, 'Supresso-Luwak-Prestige-Collection-1-Can-x-210g', 'https://shopee.co.id/product/283021328/3442033247/', 'https://www.blibli.com/p/supresso-luwak-prestige-arabica-coffee-capsules-nespresso-compatible/ps--INT-60044-00061', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:28');
INSERT INTO `master_produk` VALUES (88, 8, 4, NULL, NULL, NULL, 'Supresso Luwak Twin Value Set (Coffee Beans)', 'supresso-luwak-twin-value-set-coffee-beans-20021', '20021', NULL, 'You know it, you love it. Chocolaty, warm, and inviting; what more can one want? Double up on your favourite Luwak Prestige Beans with the Luwak Twin Bundle for a reduced price.', 'Can', '2 Can x 100g', 653600.00, 'images/uploads/1774422565_p_supresso-luwak-twin-value-set-coffee-beans-20021.webp', '[\"SUPRESSO/70-Luwak-Twin-Bundle-(Coffee-Beans)-2.webp\", \"SUPRESSO/70-Luwak-Twin-Bundle-(Coffee-Beans)-3.webp\", \"SUPRESSO/70-Luwak-Twin-Bundle-(Coffee-Beans)-4.webp\"]', 1, NULL, NULL, 'Supresso-Luwak-Twin-Value-Set-(Coffee-Beans)-2-Can-x-100g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:28');
INSERT INTO `master_produk` VALUES (89, 8, 4, NULL, NULL, 11, 'Supresso Manglayang Coffee Beans', 'supresso-manglayang-coffee-beans-sup015b', 'SUP015B', 'Sirop maple - Buah segar - Plum asam', 'Famous for its traditional coffee cultivation that retains its original character and distinctive flavours, our Manglayang Arabica coffee provides a smooth, medium body. The gentle plum acidity flavour it exudes, complements its sweet maple syrup notes, leaving a fruity lingering mouthfeel.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774407692_p_supresso-manglayang-coffee-beans-sup015b.png', '[\"SUPRESSO/CANS-5-MANG-2.webp\", \"SUPRESSO/CANS-5-MANG-3.webp\"]', 0, '2024-11-07 09:26:54', 'https://indracostore.com/product/Supresso-Manglayang-Coffee-Beans-1-Can-x-200g', 'Supresso-Manglayang-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/21217483227/', 'https://www.blibli.com/p/supresso-manglayang-coffee-beans/ps--INT-60044-00094', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:29:01');
INSERT INTO `master_produk` VALUES (90, 8, 4, NULL, NULL, 6, 'Supresso Ombre Blend Coffee Beans', 'supresso-ombre-blend-coffee-beans-sup023b', 'SUP023B', 'Rich Choco Caramel - Nutty - Spicy - Sweet Chocolaty', '100% Robusta. A robusta blend consisting of only Indonesian beans roasted to Full City roast. Characterised with no acidity and a strong body, rich choco caramel aftertastes and woody nuttiness in its undertones complete this blend.', 'Can', '1 Can x 200g', 90500.00, 'images/uploads/1774419998_p_supresso-ombre-blend-coffee-beans-sup023b.webp', '[\"SUPRESSO/Ombre-Blend-Coffee-Beans-200-2.webp\", \"SUPRESSO/Ombre-Blend-Coffee-Beans-200-3.webp\", \"SUPRESSO/Ombre-Blend-Coffee-Beans-200-4.webp\"]', 0, '2024-11-07 09:10:41', 'https://indracostore.com/product/Supresso-Ombre-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Ombre-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/18464712785/', 'https://www.blibli.com/p/supresso-ombre-blend-coffee-beans-200g/ps--INT-60044-00095', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:40:25');
INSERT INTO `master_produk` VALUES (91, 8, 4, NULL, NULL, NULL, 'Supresso Papua Coffee Beans', 'supresso-papua-coffee-beans-sup014b', 'SUP014B', 'Manis lembut - Cokelat - Buah segar - Nuansa tembakau', 'A perfect summer brew when chilled, our 100% Arabica Papua coffee has the characteristics of the coffee coincide with those found in chocolate. This heavy-bodied coffee has a delicate sweetness of fruity tones and hints of tobacco notes that tastes chocolaty as it cools off.', 'Can', '1 Can x 200g', 96000.00, 'SUPRESSO/CANS-14-papua-1.webp', '[\"SUPRESSO/CANS-14-papua-2.webp\", \"SUPRESSO/CANS-14-papua-3.webp\"]', 1, NULL, NULL, 'Supresso-Papua-Coffee-Beans-1-Can-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:29');
INSERT INTO `master_produk` VALUES (92, 8, 4, NULL, NULL, 12, 'Supresso West Java Coffee Beans', 'supresso-west-java-coffee-beans-sup016b', 'SUP016B', 'Rasa anggur - Buah beri - Madu manis', 'West Java coffees\' sour flavour is not too dominant yet not too earthy. They have a berry-like, wine taste with a sweet honey aroma that taste great on their own or paired well with dark chocolate desserts that accentuates its flavour. To bring out its earthiness, enjoy it with a hearty brunch made with cheese, mushrooms or bacon.', 'Can', '1 Can x 200g', 94500.00, 'images/uploads/1774407795_p_supresso-west-java-coffee-beans-sup016b.png', '[\"SUPRESSO/CANS_6_west_2.webp\", \"SUPRESSO/CANS_6_west_21.webp\"]', 0, '2024-11-07 09:27:33', 'https://indracostore.com/product/Supresso-West-Java-Coffee-Beans-1-Can-x-200g', 'Supresso-West-Java-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/3493491019/', 'https://www.blibli.com/p/supresso-west-java-coffee-beans/ps--INT-60044-00087', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:30:14');
INSERT INTO `master_produk` VALUES (93, 8, 4, NULL, NULL, NULL, 'Top 3 Bestsellers Value Set (Coffee Beans)', 'top-3-bestsellers-value-set-coffee-beans-20013', '20013', NULL, 'We\'re rolling out the red carpet! Our Top 3 Bestsellers Bundle features the most popular varieties of Supresso, so start here if you want to get to know us a little better. Convenient, delicious, and of great value - what\'s not to love?', 'Can', '3 Can x 200g', 218500.00, 'SUPRESSO/Top-3-Bestsellers-Bundle-coffee-beans-1.webp', '[\"SUPRESSO/Top-3-Bestsellers-Bundle-coffee-beans-2.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-coffee-beans-3.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-coffee-beans-4.webp\"]', 1, NULL, NULL, 'Top-3-Bestsellers-Value-Set-(Coffee-Beans)-3-Can-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:31');
INSERT INTO `master_produk` VALUES (94, 8, 4, NULL, NULL, NULL, 'Top 5 Bestsellers Value Set (Coffee Beans)', 'top-5-bestsellers-value-set-coffee-beans-20028', '20028', NULL, 'Is the Top 3 not enough? Fret not; we have the Top 5 too! Our Top 5 Bestsellers Bundle, like its namesake, includes five of our best-selling variants from us. Be your own barista with this bundle, which includes a different variety, for your every day and every week.', 'Can', '5 Can x 200g', 398000.00, 'SUPRESSO/Top-5-Bestsellers-Bundle-coffee-beans-1.webp', '[\"SUPRESSO/Top-5-Bestsellers-Bundle-coffee-beans-2.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-coffee-beans-3.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-coffee-beans-4.webp\"]', 1, NULL, NULL, 'Top-5-Bestsellers-Value-Set-(Coffee-Beans)-5-Can-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:31');
INSERT INTO `master_produk` VALUES (95, 8, 4, 1, 1, 8, 'Supresso Aceh Gayo Coffee Beans', 'supresso-aceh-gayo-coffee-beans-sup011b', 'SUP011B', 'Nuansa rempah - Karamel & Cokelat - Buah segar - Natural', 'Aceh Gayo coffee is often used in most coffee shops commonly for cafe latte. It has light earthy notes with a mild body and bittersweet spicy chocolate taste. Soft in acidity, this coffee reveals some elegant caramel-fruity flavours, marrying a perfect combination of spicy and sweet. Its unique taste will make you crave for more.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1773890521_p_supresso-can-aceh-gayo.png', '[\"SUPRESSO/Aceh-Gayo-Coffee-beans-200-21.webp\", \"SUPRESSO/Aceh-Gayo-Coffee-beans-200-31.webp\"]', 0, '2024-11-07 08:04:42', 'https://indracostore.com/product/Supresso-Aceh-Gayo-Coffee-Beans-1-Can-x-200g', 'Supresso-Aceh-Gayo-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/6641485876/', 'https://www.blibli.com/p/supresso-aceh-gayo-coffee-beans/ps--INT-60044-00022', 'active', 0, '2026-03-17 15:07:41', '2026-03-19 10:30:21');
INSERT INTO `master_produk` VALUES (96, 8, 4, NULL, NULL, 14, 'Supresso Bali Kintamani Coffee Beans', 'supresso-bali-kintamani-coffee-beans-sup009b', 'SUP009B', 'Rasa seimbang - Nuansa manis - Citrus segar', 'Grown in the highlands of Kintamani, this coffee has unique characteristics derived from wet processing method, making them slightly sweeter. The mild body of the coffee exudes a clean light and refreshing taste exhibiting a citrusy, fruity finish. It is a must-try for those who do not like the bitter taste.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774408142_p_supresso-bali-kintamani-coffee-beans-sup009b.png', '[\"SUPRESSO/CANS-8-bali-2.webp\", \"SUPRESSO/CANS-8-bali-3.webp\"]', 0, '2024-11-07 08:08:12', 'https://indracostore.com/product/Supresso-Bali-Kintamani-Coffee-Beans-1-Can-x-200g', 'Supresso-Bali-Kintamani-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/4241475778/', 'https://www.blibli.com/p/supresso-bali-kintamani-coffee-beans/ps--INT-60044-00018', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:31:44');
INSERT INTO `master_produk` VALUES (97, 8, 4, NULL, NULL, 3, 'Supresso Equilibre Blend Coffee Beans', 'supresso-equilibre-blend-coffee-beans-sup022b', 'SUP022B', 'Rasa sari bunga - Rempah hangat - Rasa biji asli', '50% Arabica - 50% Robusta. A 50/50 blend of Arabica and Robusta beans made with coffee grown and farmed in Indonesia and roasted with the City+ Roast mode. With a lower acidity compared to our Signature and Espresso blends, Equilibre is a balanced blend which possesses good body alongside sweet fruity and floral aftertastes with nutty and warm spice nuances.', 'Can', '1 Can x 200g', 105300.00, 'images/uploads/1774419587_p_supresso-equilibre-blend-coffee-beans-sup022b.webp', '[\"SUPRESSO/CANS-EQUI-2.webp\", \"SUPRESSO/CANS-EQUI-3.webp\"]', 0, '2024-11-07 09:01:33', 'https://indracostore.com/product/Supresso-Equilibre-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Equilibre-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/4341501379/', 'https://www.blibli.com/p/supresso-equilibre-blend-coffee-beans/ps--INT-60044-00051', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:37:32');
