INSERT INTO `master_produk` VALUES (100, 8, 4, NULL, NULL, 2, 'Supresso Espresso Blend Coffee Beans', 'supresso-espresso-blend-coffee-beans-sup008b', 'SUP008B', 'Cokelat hitam - Karamel - Sari bunga romantis', '70% Arabica - 30% Robusta. A 70/30 blend of Arabica and Robusta beans originating from the vast regions of Indonesia and roasted with the Full City Roast mode. Experience the dark chocolate hints alongside caramel and romantic florals of this one of a kind blend with medium acidity and heavy body.', 'Can', '1 Can x 200g', 113400.00, 'images/uploads/1774419506_p_supresso-espresso-blend-coffee-beans-sup008b.webp', '[\"SUPRESSO/CANS-ESPRESSO-2.webp\", \"SUPRESSO/CANS-ESPRESSO-3.webp\"]', 0, '2024-11-07 09:05:44', 'https://indracostore.com/product/Supresso-Espresso-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Espresso-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/6641493767/', 'https://www.blibli.com/p/supresso-espresso-blend-coffee-beans/ps--INT-60044-00016', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:35:46');
