INSERT INTO `master_produk` VALUES (102, 8, 4, NULL, NULL, 2, 'Supresso Espresso Blend Coffee Beans', 'supresso-espresso-blend-coffee-beans-sup008b5', 'SUP008B5', 'Cokelat hitam - Karamel - Sari bunga romantis', '70% Arabica - 30% Robusta. A 70/30 blend of Arabica and Robusta beans originating from the vast regions of Indonesia and roasted with the Full City Roast mode. Experience the dark chocolate hints alongside caramel and romantic florals of this one of a kind blend with medium acidity and heavy body.', 'Bag', '1 Bag x 500g', 161400.00, 'images/uploads/1779087160_BAG-500-SUPRESSO-ESPRESSO.webp', '[\"SUPRESSO/BAG-500G-GC-espresso-2.webp\", \"SUPRESSO/BAG-500G-GC-espresso-3.webp\"]', 0, '2025-08-06 20:51:13', 'https://indracostore.com/product/Supresso-Espresso-Blend-Coffee-Beans-1-Bag-x-500g', 'Supresso-Espresso-Blend-Coffee-Beans-1-Bag-x-500g', 'https://shopee.co.id/product/283021328/6641493767/', 'https://www.blibli.com/p/supresso-espresso-blend-coffee-beans/ps--INT-60044-00016', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 14:14:26');
INSERT INTO `master_produk` VALUES (103, 8, 4, NULL, NULL, 5, 'Supresso Exotic Blend Coffee Beans', 'supresso-exotic-blend-coffee-beans-sup021b', 'SUP021B', 'Nuansa cokelat manis - Natural - Rasa Biji Kopi Asli', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Can', '1 Can x 200g', 93200.00, 'images/uploads/1774419901_p_supresso-exotic-blend-coffee-beans-sup021b.webp', '[\"SUPRESSO/CANS-EXOTIC-2.webp\", \"SUPRESSO/CANS-EXOTIC-3.webp\"]', 0, '2024-11-07 09:08:02', 'https://indracostore.com/product/Supresso-Exotic-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Exotic-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/7041494429/', 'https://www.blibli.com/p/supresso-exotic-blend-coffee-beans/ps--INT-60044-00050', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:39:39');
INSERT INTO `master_produk` VALUES (104, 8, 4, NULL, NULL, 5, 'Supresso Exotic Blend Coffee Beans', 'supresso-exotic-blend-coffee-beans-sup021b5', 'SUP021B5', 'Nuansa cokelat manis - Natural - Rasa Biji Kopi Asli', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Bag', '1 Bag x 500g', 125600.00, 'images/uploads/1779086899_BAG-500-SUPRESSO-EXOTIC.webp', '[\"SUPRESSO/BAG-500G-GC-Exo-2.webp\", \"SUPRESSO/BAG-500G-GC-Exo-3.webp\"]', 0, '2025-08-06 20:50:41', 'https://indracostore.com/product/Supresso-Exotic-Blend-Coffee-Beans-1-Bag-x-500g', 'Supresso-Exotic-Blend-Coffee-Beans-1-Bag-x-500g', 'https://shopee.co.id/product/283021328/7041494429/', 'https://www.blibli.com/p/supresso-exotic-blend-coffee-beans/ps--INT-60044-00050', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 14:14:03');
INSERT INTO `master_produk` VALUES (105, 8, 4, NULL, NULL, 5, 'Supresso Exotic Blend Coffee Beans', 'supresso-exotic-blend-coffee-beans-sup021b10', 'SUP021B10', 'Nuansa cokelat manis - Natural - Rasa Biji Kopi Asli', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Bag', '1 Bag x 1000g', 243000.00, 'images/uploads/1779086767_BAG-1000-SUPRESSO-EXOTIC.webp', '[\"SUPRESSO/BAG-1000G-EXOTIC-2.webp\", \"SUPRESSO/BAG-1000G-EXOTIC-3.webp\"]', 0, '2024-11-07 09:07:00', 'https://indracostore.com/product/Supresso-Exotic-Blend-Coffee-Beans-1-Bag-x-1000g', 'Supresso-Exotic-Blend-Coffee-Beans-1-Bag-x-1000g', 'https://shopee.co.id/product/283021328/7041494429/', 'https://www.blibli.com/p/supresso-exotic-blend-coffee-beans/ps--INT-60044-00050', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 13:49:10');
INSERT INTO `master_produk` VALUES (106, 8, 4, NULL, NULL, 15, 'Supresso Flores Bajawa Coffee Beans', 'supresso-flores-bajawa-coffee-beans-sup010b', 'SUP010B', 'Cokelat yang lembut - Manis sari bunga - Nuansa vanilla - Karamel', 'This 100% Arabica coffee is limited in availability and one of the most popular coffees in the globe for its strongly aromatic flavour. Akin to its name, Flores coffee has an outstanding and intense floral nectareous sweetness and fragrance with hints of vanilla and chocolate fudge, leaving a lingering caramel finish.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774408259_p_supresso-flores-bajawa-coffee-beans-sup010b.png', '[\"SUPRESSO/CANS-9-flores-2.webp\", \"SUPRESSO/CANS-9-flores-3.webp\"]', 0, '2024-11-07 08:08:48', 'https://indracostore.com/product/Supresso-Flores-Bajawa-Coffee-Beans-1-Can-x-200g', 'Supresso-Flores-Bajawa-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/4641476021/', 'https://www.blibli.com/p/supresso-flores-bajawa-coffee-beans/ps--INT-60044-00020', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:32:24');
INSERT INTO `master_produk` VALUES (107, 8, 4, NULL, NULL, 29, 'Supresso Java Arabica Organic Coffee Beans', 'supresso-java-arabica-organic-coffee-beans-sup001b', 'SUP001B', 'Manis lembut - Natural - Herbal - Rasa yang tahan lama', 'One of the best farm-to-cup Indonesian coffee comes from Java. These USDA organic approved beans are grown in high altitude without the use of pesticides, herbicides, or other chemicals. With mild acidity and heavy-body, its flavour is elegantly sweet with a subtle earthiness that lingers on.', 'Can', '1 Can x 200g', 133700.00, 'images/uploads/1774413389_p_supresso-java-arabica-organic-coffee-beans-sup001b.png', '[\"SUPRESSO/CANS-13-java-arabica-2.webp\", \"SUPRESSO/CANS-13-java-arabica-3.webp\"]', 0, '2024-11-07 08:09:24', 'https://indracostore.com/product/Supresso-Java-Arabica-Organic-Coffee-Beans-1-Can-x-200g', 'Supresso-Java-Arabica-Organic-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/3641482468/', 'https://www.blibli.com/p/supresso-java-arabica-organic-coffee-beans/ps--INT-60044-00004', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:23:38');
INSERT INTO `master_produk` VALUES (108, 8, 4, NULL, NULL, 13, 'Supresso Java Coffee Beans', 'supresso-java-coffee-beans-sup004b', 'SUP004B', 'Manis - Malt yang kuat - Nuansa tembakau', 'Supresso Java Robusta coffee beans are thoroughly wet-processed, kicking off the acidity, drops the body and reduces the earthiness of the cup to a unique sweetness. Its strong malty taste with hints of tobacco notes will give a perfect combination when added with cocoa - great for brewing your delicious mocha.', 'Can', '1 Can x 200g', 94500.00, 'images/uploads/1774407982_p_supresso-java-coffee-beans-sup004b.png', '[\"SUPRESSO/CANS-7-java-2.webp\", \"SUPRESSO/CANS-7-java-3.webp\"]', 0, '2024-11-07 08:10:00', 'https://indracostore.com/product/Supresso-Java-Coffee-Beans-1-Can-x-200g', 'Supresso-Java-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/5341473533/', 'https://www.blibli.com/p/supresso-java-coffee-beans/ps--INT-60044-00086', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:30:51');
INSERT INTO `master_produk` VALUES (109, 8, 4, NULL, NULL, 10, 'Supresso Lampung Coffee Beans', 'supresso-lampung-coffee-beans-sup006b', 'SUP006B', 'Nuansa cokelat - Natural - Sentuhan rasa tembakau', 'Well-sought after by the world\'s coffee industry, this Robusta coffee gives off an immense strong-bodied bitter taste with the essence of chocolate, slightly earthy aroma and tobacco undertones. The absence of acidity is Lampung\'s trademark.', 'Can', '1 Can x 200g', 94500.00, 'images/uploads/1774407389_p_supresso-lampung-coffee-beans-sup006b.png', '[\"SUPRESSO/CANS-4-LAM-2.webp\", \"SUPRESSO/CANS-4-LAM-3.webp\"]', 0, '2024-11-07 08:10:34', 'https://indracostore.com/product/Supresso-Lampung-Coffee-Beans-1-Can-x-200g', 'Supresso-Lampung-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/3741575470/', 'https://www.blibli.com/p/supresso-lampung-coffee-beans/ps--INT-60044-00012', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:27:56');
INSERT INTO `master_produk` VALUES (110, 8, 4, NULL, NULL, 4, 'Supresso Lumiere Blend Coffee Beans', 'supresso-lumiere-blend-coffee-beans-sup020b', 'SUP020B', 'Nuansa cokelat & rempah - Natural - Sentuhan Karamel', '30% Arabica - 70% Robusta. A 30/70 blend of Arabica and Robusta beans originating from the different regions of Indonesia and roasted with the City+ Roast mode. Taste the complementary sweet chocolaty hints, warm spices and slight earthiness amongst the caramel chocolaty undertones, with lower acidity and strong body.', 'Can', '1 Can x 200g', 99900.00, 'images/uploads/1774419826_p_supresso-lumiere-blend-coffee-beans-sup020b.webp', '[\"SUPRESSO/CANS-LUMIERE-2.webp\", \"SUPRESSO/CANS-LUMIERE-3.webp\"]', 0, '2024-11-07 09:09:40', 'https://indracostore.com/product/Supresso-Lumiere-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Lumiere-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/5441495677/', 'https://www.blibli.com/p/supresso-lumiere-blend-coffee-beans/ps--INT-60044-00049', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:38:22');
INSERT INTO `master_produk` VALUES (111, 8, 4, NULL, NULL, 4, 'Supresso Lumiere Blend Coffee Beans', 'supresso-lumiere-blend-coffee-beans-sup020b10', 'SUP020B10', 'Nuansa cokelat & rempah - Natural - Sentuhan Karamel', '30% Arabica - 70% Robusta. A 30/70 blend of Arabica and Robusta beans originating from the different regions of Indonesia and roasted with the City+ Roast mode. Taste the complementary sweet chocolaty hints, warm spices and slight earthiness amongst the caramel chocolaty undertones, with lower acidity and strong body.', 'Bag', '1 Bag x 1000g', 271400.00, 'images/uploads/1779087775_BAG-1000-SUPRESSO-LUMIERE.webp', '[\"SUPRESSO/BAG-1000G-LUMIERE-2.webp\", \"SUPRESSO/BAG-1000G-LUMIERE-3.webp\"]', 0, '2024-11-07 09:09:12', 'https://indracostore.com/product/Supresso-Lumiere-Blend-Coffee-Beans-1-Bag-x-1000g', 'Supresso-Lumiere-Blend-Coffee-Beans-1-Bag-x-1000g', 'https://shopee.co.id/product/283021328/5441495677/', 'https://www.blibli.com/p/supresso-lumiere-blend-coffee-beans/ps--INT-60044-00049', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 14:04:42');
INSERT INTO `master_produk` VALUES (112, 8, 4, NULL, NULL, 4, 'Supresso Lumiere Blend Coffee Beans', 'supresso-lumiere-blend-coffee-beans-sup020b5', 'SUP020B5', 'Nuansa cokelat & rempah - Natural - Sentuhan Karamel', '30% Arabica - 70% Robusta. A 30/70 blend of Arabica and Robusta beans originating from the different regions of Indonesia and roasted with the City+ Roast mode. Taste the complementary sweet chocolaty hints, warm spices and slight earthiness amongst the caramel chocolaty undertones, with lower acidity and strong body.', 'Bag', '1 Bag x 500g', 140400.00, 'images/uploads/1779087798_BAG-500-SUPRESSO-LUMIERE.webp', '[\"SUPRESSO/BAG-500G-GC-lumiere-2.webp\", \"SUPRESSO/BAG-500G-GC-lumiere-3.webp\"]', 0, '2025-08-06 20:50:14', 'https://indracostore.com/product/Supresso-Lumiere-Blend-Coffee-Beans-1-Bag-x-500g', 'Supresso-Lumiere-Blend-Coffee-Beans-1-Bag-x-500g', 'https://shopee.co.id/product/283021328/5441495677/', 'https://www.blibli.com/p/supresso-lumiere-blend-coffee-beans/ps--INT-60044-00049', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 14:15:46');
INSERT INTO `master_produk` VALUES (113, 8, 4, NULL, NULL, 28, 'Supresso Luwak Prestige Arabica Coffee Beans', 'supresso-luwak-prestige-arabica-coffee-beans-sup002b', 'SUP002B', 'Karamel cokelat - Lembut dan manis - Rasa mewah', 'Characterised by its velvety and sweet chocolaty-caramel taste profile, Luwak is a rare and exotic coffee that leaves every coffee lover intrigued and typically found on bucket lists around the world. A perfect cup for you if you like your coffee smooth with a clean aftertaste.', 'Can', '1 Can x 100g', 488700.00, 'images/uploads/1774422532_p_supresso-luwak-prestige-arabica-coffee-beans-sup002b.webp', '[\"SUPRESSO/54-luwak-prestige-arabica-coffee-beans-2.webp\", \"SUPRESSO/54-luwak-prestige-arabica-coffee-beans-3.webp\"]', 0, '2024-11-07 08:11:14', 'https://indracostore.com/product/Supresso-Luwak-Prestige-Arabica-Coffee-Beans-1-Can-x-100g', 'Supresso-Luwak-Prestige-Arabica-Coffee-Beans-1-Can-x-100g', 'https://shopee.co.id/product/283021328/3441563209/', 'https://www.blibli.com/p/supresso-luwak-prestige-arabica-coffee-beans/ps--INT-60044-00002', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:22:11');
INSERT INTO `master_produk` VALUES (114, 8, 4, NULL, NULL, 27, 'Supresso Peaberry Coffee Beans', 'supresso-peaberry-coffee-beans-sup012b', 'SUP012B', 'Herbal - Buah segar - Rasa manis hingga akhir', 'Peaberry is known to be significantly sweeter than other beans because of its exclusive access to the fruit. With delicate fruity fragrance, as well as subtle nutty and herbal character, the medium acidity enveloped in sweetness carries through into the long finish.', 'Can', '1 Can x 200g', 152600.00, 'images/uploads/1774421066_p_supresso-peaberry-coffee-beans-sup012b.webp', '[\"SUPRESSO/CANS-2-PEA-2.webp\", \"SUPRESSO/CANS-2-PEA-3.webp\"]', 0, '2024-11-07 08:23:41', 'https://indracostore.com/product/Supresso-Peaberry-Coffee-Beans-1-Can-x-200g', 'Supresso-Peaberry-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/3341588340/', 'https://www.blibli.com/p/supresso-peaberry-coffee-beans/ps--INT-60044-00024', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:19:17');
INSERT INTO `master_produk` VALUES (115, 8, 4, NULL, NULL, 1, 'Supresso Signature Blend Coffee Beans', 'supresso-signature-blend-coffee-beans-sup007b', 'SUP007B', 'Buah tropis - Rempah hangat - Karamel Cokelat', '100% Arabica. Pure 100% Arabica coffee beans originating from various regions in Indonesia, and roasted with the Full City Roast mode. Relish in unmatched acidity along with hints of warm spices, tropical fruits and chocolaty caramel nuances.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774419403_p_supresso-signature-blend-coffee-beans-sup007b.webp', '[\"SUPRESSO/CANS-SIGNA-2.webp\", \"SUPRESSO/CANS-SIGNA-3.webp\"]', 0, '2024-11-07 09:14:04', 'https://indracostore.com/product/Supresso-Signature-Blend-Coffee-Beans-1-Can-x-200g', 'Supresso-Signature-Blend-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/3641590300/', 'https://www.blibli.com/p/supresso-signature-blend-coffee-beans/ps--INT-60044-00014', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:35:03');
