INSERT INTO `master_produk` VALUES (117, 8, 4, NULL, NULL, 1, 'Supresso Signature Blend Coffee Beans', 'supresso-signature-blend-coffee-beans-sup007b5', 'SUP007B5', 'Buah tropis - Rempah hangat - Karamel Cokelat', '100% Arabica. Pure 100% Arabica coffee beans originating from various regions in Indonesia, and roasted with the Full City Roast mode. Relish in unmatched acidity along with hints of warm spices, tropical fruits and chocolaty caramel nuances.', 'Bag', '1 Bag x 500g', 191700.00, 'images/uploads/1779087385_BAG-500-SUPRESSO-SIGNATURE.webp', '[\"SUPRESSO/BAG-500G-GC-signature-2.webp\", \"SUPRESSO/BAG-500G-GC-signature-3.webp\"]', 0, '2025-08-06 20:49:22', 'https://indracostore.com/product/Supresso-Signature-Blend-Coffee-Beans-1-Bag-x-500g', 'Supresso-Signature-Blend-Coffee-Beans-1-Bag-x-500g', 'https://shopee.co.id/product/283021328/3641590300/', 'https://www.blibli.com/p/supresso-signature-blend-coffee-beans/ps--INT-60044-00014', 'active', 0, '2026-03-17 15:07:41', '2026-05-18 14:14:53');
INSERT INTO `master_produk` VALUES (118, 8, 4, NULL, NULL, 9, 'Supresso Sumatra Mandheling Coffee Beans', 'supresso-sumatra-mandheling-coffee-beans-sup005b', 'SUP005B', 'Sensasi segar - Manis berempah - Natural', 'These Arabica coffee beans are not only rare and rich in history but also one of the highly recognised by gourmet coffee producers in the world. The syrupy, full body of Sumatra Mandheling, combined with its muted acidity, makes an elegant, smooth cup of coffee. A blend of sweet and spicy, exuding an exotic flavour.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774406437_p_supresso-sumatra-mandheling-coffee-beans-sup005b.png', '[\"SUPRESSO/CANS-3-SUMA-2.webp\", \"SUPRESSO/CANS-3-SUMA-3.webp\"]', 0, '2024-11-07 08:24:53', 'https://indracostore.com/product/Supresso-Sumatra-Mandheling-Coffee-Beans-1-Can-x-200g', 'Supresso-Sumatra-Mandheling-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/7541472893/', 'https://www.blibli.com/p/supresso-sumatra-mandheling-coffee-beans/ps--INT-60044-00010', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:26:48');
INSERT INTO `master_produk` VALUES (119, 8, 4, NULL, NULL, 30, 'Supresso Sumatra Mandheling Rainforest Coffee Beans', 'supresso-sumatra-mandheling-rainforest-coffee-beans-sup003b', 'SUP003B', 'Kesegaran bunga dan buah - Rempah - Natural', 'Considered by many to be the best coffee beans that Sumatra produces, our Rainforest Alliance Certified Sumatra Mandheling Rainforest coffee is packed with sweet floral and fruity flavours, and a spicy aroma that finishes off with a slightly earthy undertone. You can try pairing our Sumatran coffee with sweet and creamy desserts.', 'Can', '1 Can x 200g', 141800.00, 'images/uploads/1774422644_p_supresso-sumatra-mandheling-rainforest-coffee-beans-sup003b.webp', '[\"SUPRESSO/CANS-12-sumrain-2.webp\", \"SUPRESSO/CANS-12-sumrain-3.webp\"]', 0, '2024-11-07 08:24:16', 'https://indracostore.com/product/Supresso-Sumatra-Mandheling-Rainforest-Coffee-Beans-1-Can-x-200g', 'Supresso-Sumatra-Mandheling-Rainforest-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/5441473378/', 'https://www.blibli.com/p/supresso-sumatra-mandheling-rainforest-coffee-beans/ps--INT-60044-00006', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:24:02');
INSERT INTO `master_produk` VALUES (120, 8, 4, NULL, NULL, 16, 'Supresso Toraja Kalosi Coffee Beans', 'supresso-toraja-kalosi-coffee-beans-sup013b', 'SUP013B', 'Rempah hangat - Sentuhan rasa manis dan lembut', 'Our Supresso Toraja Kalosi is highly valued among Japan\'s coffee drinkers because of its quality traditional processing, offering multiple layers of flavours that reveal something upon each sip. The heavy-bodied coffee is low in acidity, and its delicate aroma denotes warm spices with a sweet and smooth aftertaste.', 'Can', '1 Can x 200g', 128300.00, 'images/uploads/1774408355_p_supresso-toraja-kalosi-coffee-beans-sup013b.png', '[\"SUPRESSO/CANS-10-toraja-2.webp\", \"SUPRESSO/CANS-10-toraja-3.webp\"]', 0, '2024-11-07 08:25:28', 'https://indracostore.com/product/Supresso-Toraja-Kalosi-Coffee-Beans-1-Can-x-200g', 'Supresso-Toraja-Kalosi-Coffee-Beans-1-Can-x-200g', 'https://shopee.co.id/product/283021328/6441491551/', 'https://www.blibli.com/p/supresso-toraja-kalosi-coffee-beans/ps--INT-60044-00026', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:33:09');
INSERT INTO `master_produk` VALUES (121, 8, 4, NULL, NULL, NULL, 'Top 3 Bestsellers Value Set (Ground Coffee)', 'top-3-bestsellers-value-set-ground-coffee-20014', '20014', NULL, 'We\'re rolling out the red carpet! Our Top 3 Bestsellers Bundle features the most popular varieties of Supresso, so start here if you want to get to know us a little better. Convenient, delicious, and of great value - what\'s not to love?', 'Box', '1 Box x 800g', 171000.00, 'SUPRESSO/Top-3-Bestsellers-Bundle-ground-coffee-1.webp', '[\"SUPRESSO/Top-3-Bestsellers-Bundle-ground-coffee-2.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-ground-coffee-3.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-ground-coffee-4.webp\"]', 1, NULL, NULL, 'Top-3-Bestsellers-Value-Set-(Ground-Coffee)-1-Box-x-800g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (122, 8, 4, NULL, NULL, NULL, 'Top 5 Bestsellers Value Set (Ground Coffee)', 'top-5-bestsellers-value-set-ground-coffee-20029', '20029', NULL, 'Is the Top 3 not enough? Fret not; we have the Top 5 too! Our Top 5 Bestsellers Bundle, like its namesake, includes five of our best-selling variants from us. Be your own barista with this bundle, which includes a different variety, for your every day and every week.', 'Box', '1 Box x 1250g', 305900.00, 'SUPRESSO/Top-5-Bestsellers-Bundle-ground-coffee-1.webp', '[\"SUPRESSO/Top-5-Bestsellers-Bundle-ground-coffee-2.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-ground-coffee-3.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-ground-coffee-4.webp\"]', 1, NULL, NULL, 'Top-5-Bestsellers-Value-Set-(Ground-Coffee)-1-Box-x-1250g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (123, 8, 4, NULL, NULL, 14, 'Supresso Bali Kintamani Ground Coffee', 'supresso-bali-kintamani-ground-coffee-sup009gb', 'SUP009GB', 'Rasa seimbang - Nuansa manis - Citrus segar', 'Grown in the highlands of Kintamani, this coffee has unique characteristics derived from wet processing method, making them slightly sweeter. The mild body of the coffee exudes a clean light and refreshing taste exhibiting a citrusy, fruity finish. It is a must-try for those who do not like the bitter taste.', 'Box', '1 Box x 200g', 74200.00, 'images/uploads/1774413620_p_supresso-bali-kintamani-ground-coffee-sup009gb.png', '[\"SUPRESSO/Bali-Kintamani-Coffee-ground-200-2.webp\", \"SUPRESSO/Bali-Kintamani-Coffee-ground-200-3.webp\", \"SUPRESSO/Bali-Kintamani-Coffee-ground-200-4.webp\"]', 1, NULL, NULL, 'Supresso-Bali-Kintamani-Ground-Coffee-1-Box-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (124, 8, 4, NULL, NULL, 10, 'Supresso Lampung Ground Coffee', 'supresso-lampung-ground-coffee-sup006gb', 'SUP006GB', 'Nuansa cokelat - Natural - Sentuhan rasa tembakau', 'Well-sought after by the world\'s coffee industry, this Robusta coffee gives off an immense strong-bodied bitter taste with the essence of chocolate, slightly earthy aroma and tobacco undertones. The absence of acidity is Lampung\'s trademark.', 'Box', '1 Box x 200g', 48100.00, 'images/uploads/1774413243_p_supresso-lampung-ground-coffee-sup006gb.png', '[\"SUPRESSO/Lampung-Coffee-ground-200-2.webp\", \"SUPRESSO/Lampung-Coffee-ground-200-3.webp\", \"SUPRESSO/Lampung-Coffee-ground-200-4.webp\"]', 1, NULL, NULL, 'Supresso-Lampung-Ground-Coffee-1-Box-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (125, 8, 4, NULL, NULL, 27, 'Supresso Peaberry Ground Coffee', 'supresso-peaberry-ground-coffee-sup012gb', 'SUP012GB', 'Herbal - Buah segar - Rasa manis hingga akhir', 'Peaberry is known to be significantly sweeter than other beans because of its exclusive access to the fruit. With delicate fruity fragrance, as well as subtle nutty and herbal character, the medium acidity enveloped in sweetness carries through into the long finish.', 'Box', '1 Box x 200g', 110500.00, 'images/uploads/1774421028_p_supresso-peaberry-ground-coffee-sup012gb.webp', '[\"SUPRESSO/Peaberry-Coffee-ground-200-2.webp\", \"SUPRESSO/Peaberry-Coffee-ground-200-3.webp\", \"SUPRESSO/Peaberry-Coffee-ground-200-4.webp\"]', 1, NULL, NULL, 'Supresso-Peaberry-Ground-Coffee-1-Box-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (126, 8, 4, NULL, NULL, 9, 'Supresso Sumatra Mandheling Ground Coffee', 'supresso-sumatra-mandheling-ground-coffee-sup005gb', 'SUP005GB', 'Sensasi segar - Manis berempah - Natural', 'These Arabica coffee beans are not only rare and rich in history but also one of the highly recognised by gourmet coffee producers in the world. The syrupy, full body of Sumatra Mandheling, combined with its muted acidity, makes an elegant, smooth cup of coffee. A blend of sweet and spicy, exuding an exotic flavour.', 'Box', '1 Box x 200g', 96200.00, 'images/uploads/1774413138_p_supresso-sumatra-mandheling-ground-coffee-sup005gb.png', '[\"SUPRESSO/GROUND-SUMATRA-2-produk-web.webp\", \"SUPRESSO/GROUND-SUMATRA-3-produk-web.webp\"]', 1, NULL, NULL, 'Supresso-Sumatra-Mandheling-Ground-Coffee-1-Box-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (127, 8, 4, NULL, NULL, 16, 'Supresso Toraja Kalosi Ground Coffee', 'supresso-toraja-kalosi-ground-coffee-sup013gb', 'SUP013GB', 'Rempah hangat - Sentuhan rasa manis dan lembut', 'Our Supresso Toraja Kalosi is highly valued among Japan\'s coffee drinkers because of its quality traditional processing, offering multiple layers of flavours that reveal something upon each sip. The heavy-bodied coffee is low in acidity, and its delicate aroma denotes warm spices with a sweet and smooth aftertaste.', 'Box', '1 Box x 200g', 89700.00, 'images/uploads/1774414725_p_supresso-toraja-kalosi-ground-coffee-sup013gb.png', '[\"SUPRESSO/Toraja-Kalosi-Coffee-ground-200-2.webp\", \"SUPRESSO/Toraja-Kalosi-Coffee-ground-200-3.webp\", \"SUPRESSO/Toraja-Kalosi-Coffee-ground-200-4.webp\"]', 1, NULL, NULL, 'Supresso-Toraja-Kalosi-Ground-Coffee-1-Box-x-200g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (128, 8, 4, NULL, NULL, NULL, 'Supresso Arabica Value Set (Capsules)', 'supresso-arabica-value-set-capsules-20008', '20008', '-', 'This Arabica Bundle is truly the creme de la creme, where all variants are 100% Arabica and of Single Origin, perfect for those of us who rely on caffeine to get through the day. Its the perfect sampling of sweet and refreshing, that is sure to open your mind and taste buds to a whole new world of coffee.', 'Box', '3 Box x 60g', 141550.00, 'SUPRESSO/Arabica-Bundle-capsules-1.webp', '[\"SUPRESSO/Arabica-Bundle-capsules-2.webp\", \"SUPRESSO/Arabica-Bundle-capsules-3.webp\", \"SUPRESSO/Arabica-Bundle-capsules-4.webp\"]', 0, '2024-03-12 13:28:08', NULL, 'Supresso-Arabica-Value-Set-(Capsules)-3-Box-x-60g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (129, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Arabica Gold Coffee Capsules', 'supresso-balicafe-arabica-gold-coffee-capsules-10331', '10331', 'Herbal - Aroma kuat - Sensasi sitrus', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen arabica Bali coffee beans and with a full city roasting method so that it produces fragrant arabica coffee with a Balinese coffee taste.', 'Box', '10 Capsules x 6g', 84500.00, 'images/uploads/1774409820_p_BaliCafe-Arabica-Gold-Coffee-Capsules-60g.png', '[\"SUPRESSO/77-BaliCafe-Arabica-Gold-Coffee-Capsules-2.webp\", \"SUPRESSO/77-BaliCafe-Arabica-Gold-Coffee-Capsules-3.webp\"]', 0, '2025-02-14 10:32:29', '', 'Supresso-BaliCafe-Arabica-Gold-Coffee-Capsules-10-Capsules-x-6g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (130, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Luwak Arabica Coffee Capsules', 'supresso-balicafe-luwak-arabica-coffee-capsules-10336', '10336', 'Sensasi segar buah - Herbal - Rasa rempah Bali - Nuansa cokelat', 'After having a great success with SUPRESSO, we, INDRACO 1971 DEWATA, proudly present BaliCafe Coffee Civet Arabica. It comes from chosen arabica Bali coffee beans, is fermented through Civet? digestion system, and roasted with a full city method so that it produces fragrant civet arabica coffee with a Balinese coffee taste.', 'Box', '10 Capsules x 6g', 146000.00, 'images/uploads/1774409266_p_BaliCafe-Luwak-Arabica-Coffee-Capsules-60g.png', '[\"SUPRESSO/BaliCafe-Luwak-Arabica-Coffee-Capsules-60-2.webp\", \"SUPRESSO/BaliCafe-Luwak-Arabica-Coffee-Capsules-60-3.webp\", \"SUPRESSO/BaliCafe-Luwak-Arabica-Coffee-Capsules-60-4.webp\"]', 0, '2024-03-12 14:33:42', '', 'Supresso-BaliCafe-Luwak-Arabica-Coffee-Capsules-10-Capsules-x-6g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (131, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Peaberry Robusta Coffee Capsules', 'supresso-balicafe-peaberry-robusta-coffee-capsules-10338', '10338', 'Sensasi rasa cokelat karamel - Rasa natural Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen peaberry robusta Bali coffee beans and with a full city+ roasting method so that it produces fragrant peaberry robusta coffee with a Balinese coffee taste.', 'Box', '10 Capsules x 6g', 84500.00, 'images/uploads/1774409240_p_BaliCafe-Peaberry-Robusta-Coffee-Capsules-60g.png', '[\"SUPRESSO/78-BaliCafe-Peaberry-Robusta-Coffee-Capsules-2.webp\", \"SUPRESSO/78-BaliCafe-Peaberry-Robusta-Coffee-Capsules-3.webp\"]', 0, '2025-02-14 10:32:57', '', 'Supresso-BaliCafe-Peaberry-Robusta-Coffee-Capsules-10-Capsules-x-6g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (132, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Robusta Coffee Capsules', 'supresso-balicafe-robusta-coffee-capsules-10343', '10343', 'Sensasi rasa cokelat - Agak manis - Rasa natural Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen robusta Bali coffee beans and with a full city roasting method so that it produces fragrant robusta coffee with a Balinese coffee taste.', 'Box', '10 Capsules x 6g', 84500.00, 'images/uploads/1774409166_p_BaliCafe-Robusta-Coffee-Capsules-60g.png', '[\"SUPRESSO/81-BaliCafe-Robusta-Coffee-Capsules-2.webp\", \"SUPRESSO/81-BaliCafe-Robusta-Coffee-Capsules-3.webp\"]', 0, '2025-02-14 10:33:35', '', 'Supresso-BaliCafe-Robusta-Coffee-Capsules-10-Capsules-x-6g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (133, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Sunset Blend Coffee Capsules', 'supresso-balicafe-sunset-blend-coffee-capsules-10348', '10348', 'Sensasi sitrus & manis - Herbal segar - Rasa rempah Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen and blended arabica - robusta Bali coffee beans and with a full city roasting method so that it produces fragrant robusta coffee with a Balinese coffee taste.', 'Box', '10 Capsules x 6g', 84500.00, 'images/uploads/1774409142_p_BaliCafe-Sunset-Blend-Coffee-Capsules-60g.png', '[\"SUPRESSO/82-BaliCafe-Sunset-Blend-Coffee-Capsules-2.webp\", \"SUPRESSO/82-BaliCafe-Sunset-Blend-Coffee-Capsules-3.webp\"]', 0, '2025-02-14 10:33:57', '', 'Supresso-BaliCafe-Sunset-Blend-Coffee-Capsules-10-Capsules-x-6g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (134, 8, 4, NULL, NULL, NULL, 'Supresso Java Value Set (Capsules)', 'supresso-java-value-set-capsules-20002', '20002', '-', 'Want to know the taste of Java? It\'s all in this bundle, which brings together: Java and West Java. Each variety contains two distinct flavours - \"West Java\" represents a heavier body while \"Java\" is uniquely malty, sweet and has a slightly lighter body.', 'Box', '2 Box x 60g', 91200.00, 'images/uploads/1774414035_p_supresso-java-value-set-capsules-20002.jpg', '[\"SUPRESSO/Java-Bundle-coffee-capsules-2.webp\", \"SUPRESSO/Java-Bundle-coffee-capsules-3.webp\", \"SUPRESSO/Java-Bundle-coffee-capsules-4.webp\"]', 0, '2024-03-12 13:38:34', '', 'Supresso-Java-Value-Set-(Capsules)-2-Box-x-60g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:50');
INSERT INTO `master_produk` VALUES (135, 8, 4, NULL, NULL, NULL, 'Supresso Luwak Twin Value Set (Capsules)', 'supresso-luwak-twin-value-set-capsules-20019', '20019', NULL, 'You know it, you love it. Chocolaty, warm, and inviting; what more can one want? Double up on your favourite Luwak Prestige Capsule with the Luwak Twin Bundle for a reduced price.', 'Box', '2 Box x 60g', 209000.00, 'images/uploads/1774422494_p_supresso-luwak-twin-value-set-capsules-20019.webp', '[\"SUPRESSO/68-Luwak-Twin-Bundle-(Capsules)-2.webp\", \"SUPRESSO/68-Luwak-Twin-Bundle-(Capsules)-3.webp\", \"SUPRESSO/68-Luwak-Twin-Bundle-(Capsules)-4.webp\"]', 1, NULL, NULL, 'Supresso-Luwak-Twin-Value-Set-(Capsules)-2-Box-x-60g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:51');
INSERT INTO `master_produk` VALUES (136, 8, 4, NULL, NULL, NULL, 'Supresso Robusta Value Set (Capsules)', 'supresso-robusta-value-set-capsules-20007', '20007', NULL, 'Like your Indonesian coffee strong and robust? The Robusta bundle consisting of only Single Origin Robusta coffee, is guaranteed to knock you off your feet and keep you alert through your afternoon workday.', 'Box', '3 Box x 60g', 172000.00, 'SUPRESSO/Robusta-Bundle-capsules-1.webp', '[\"SUPRESSO/Robusta-Bundle-capsules-2.webp\", \"SUPRESSO/Robusta-Bundle-capsules-3.webp\", \"SUPRESSO/Robusta-Bundle-capsules-4.webp\"]', 1, NULL, NULL, 'Supresso-Robusta-Value-Set-(Capsules)-3-Box-x-60g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:51');
INSERT INTO `master_produk` VALUES (137, 8, 4, NULL, NULL, 7, 'Supresso Decafeine Blend Coffee Capsules', 'supresso-decafeine-blend-coffee-capsules-sup024c', 'SUP024C', 'Boldly Roasted - Notes of Caramel & Spices - Delicate Acidity', 'Teeming with exceptional fragrances alongside hints of caramel and spices, this dark roast coffee is smooth and medium-bodied with delicate acidity, all wrapped in a decaffeinated package.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493730_p_supresso-decafeine-blend-coffee-capsules-sup024c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc072_dec_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc073_dec_1ks_1ks.webp\"]', 0, '2025-10-09 15:06:37', 'https://indracostore.com/product/supresso-decafeine-blend-coffee-capsules-1-box-x-60g', 'supresso-decafeine-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/23105743277/', 'https://www.blibli.com/p/supresso-decafeine-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00103', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:55:30');
INSERT INTO `master_produk` VALUES (138, 8, 4, NULL, NULL, 3, 'Supresso Equilibre Blend Coffee Capsules', 'supresso-equilibre-blend-coffee-capsules-sup022c', 'SUP022C', 'Rasa sari bunga - Rempah hangat - Rasa biji asli', '50% Arabica - 50% Robusta. A 50/50 blend of Arabica and Robusta beans made with coffee grown and farmed in Indonesia and roasted with the City+ Roast mode. With a lower acidity compared to our Signature and Espresso blends, Equilibre is a balanced blend which possesses good body alongside sweet fruity and floral aftertastes with nutty and warm spice nuances.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493434_p_supresso-equilibre-blend-coffee-capsules-sup022c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc032_equ_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc033_equ_1ks.webp\"]', 0, '2025-10-09 15:01:58', 'https://indracostore.com/product/supresso-equilibre-blend-coffee-capsules-1-box-x-60g', 'supresso-equilibre-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/16691338389/', 'https://www.blibli.com/p/supresso-equilibre-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00099', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:50:34');
INSERT INTO `master_produk` VALUES (139, 8, 4, NULL, NULL, 2, 'Supresso Espresso Blend Coffee Capsules', 'supresso-espresso-blend-coffee-capsules-sup008c', 'SUP008C', '70% Arabica - 30% Robusta. A 70/30 blend of Arabica and Robusta beans originating from the vast regions of Indonesia and roasted with the Full City Roast mode.', '70% Arabica - 30% Robusta. A 70/30 blend of Arabica and Robusta beans originating from the vast regions of Indonesia and roasted with the Full City Roast mode. Experience the dark chocolate hints alongside caramel and romantic florals of this one of a kind blend with medium acidity and heavy body.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493372_p_supresso-espresso-blend-coffee-capsules-sup008c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc022_esp_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc023_esp_1ks.webp\"]', 0, '2025-10-09 15:08:34', 'https://indracostore.com/product/supresso-espresso-blend-coffee-capsules-1-box-x-60g', 'supresso-espresso-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/23410389210/', 'https://www.blibli.com/p/supresso-espresso-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00098', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:49:32');
INSERT INTO `master_produk` VALUES (140, 8, 4, NULL, NULL, 5, 'Supresso Exotic Blend Coffee Capsules', 'supresso-exotic-blend-coffee-capsules-sup021c', 'SUP021C', 'Nuansa cokelat manis - Natural - Rasa Biji Kopi Asli', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493609_p_supresso-exotic-blend-coffee-capsules-sup021c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc052_exo_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc053_exo_1ks.webp\"]', 0, '2025-10-09 15:02:37', 'https://indracostore.com/product/supresso-exotic-blend-coffee-capsules-1-box-x-60g', 'supresso-exotic-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/12097903894/', 'https://www.blibli.com/p/supresso-exotic-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00101', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:53:29');
INSERT INTO `master_produk` VALUES (141, 8, 4, NULL, NULL, 4, 'Supresso Lumiere Blend Coffee Capsules', 'supresso-lumiere-blend-coffee-capsules-sup020c', 'SUP020C', 'Nuansa cokelat & rempah - Natural - Sentuhan Karamel', '30% Arabica - 70% Robusta. A 30/70 blend of Arabica and Robusta beans originating from the different regions of Indonesia and roasted with the City+ Roast mode. Taste the complementary sweet chocolaty hints, warm spices and slight earthiness amongst the caramel chocolaty undertones, with lower acidity and strong body.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493539_p_supresso-lumiere-blend-coffee-capsules-sup020c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc042_lum_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc043_lum_1ks.webp\"]', 0, '2025-10-09 15:07:36', 'https://indracostore.com/product/supresso-lumiere-blend-coffee-capsules-1-box-x-60g', 'supresso-lumiere-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/19368319482/', 'https://www.blibli.com/p/supresso-lumiere-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00100', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:52:19');
INSERT INTO `master_produk` VALUES (142, 8, 4, NULL, NULL, 6, 'Supresso Ombre Blend Coffee Capsules', 'supresso-ombre-blend-coffee-capsules-sup023c', 'SUP023C', 'Rich Choco Caramel - Nutty - Spicy - Sweet Chocolaty', '100% Robusta. A robusta blend consisting of only Indonesian beans roasted to Full City roast. Characterised with no acidity and a strong body, rich choco caramel aftertastes and woody nuttiness in its undertones complete this blend.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493662_p_supresso-ombre-blend-coffee-capsules-sup023c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc062_omb_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc063_omb_1ks_1ks.webp\"]', 0, '2025-10-09 15:03:19', 'https://indracostore.com/product/supresso-ombre-blend-coffee-capsules-1-box-x-60g', 'supresso-ombre-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/18464714017/', 'https://www.blibli.com/p/supresso-ombre-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00102', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:54:22');
INSERT INTO `master_produk` VALUES (143, 8, 4, NULL, NULL, 1, 'Supresso Signature Blend Coffee Capsules', 'supresso-signature-blend-coffee-capsules-sup007c', 'SUP007C', 'Buah tropis - Rempah hangat - Karamel Cokelat', '100% Arabica. Pure 100% Arabica coffee beans originating from various regions in Indonesia, and roasted with the Full City Roast mode. Relish in unmatched acidity along with hints of warm spices, tropical fruits and chocolaty caramel nuances.', 'Box', '1 Box x 60g', 105300.00, 'images/uploads/1774493286_p_supresso-signature-blend-coffee-capsules-sup007c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_gc012_sign_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_gc013_sign_1ks.webp\"]', 0, '2025-10-09 15:05:09', 'https://indracostore.com/product/supresso-signature-blend-coffee-capsules-1-box-x-60g', 'supresso-signature-blend-coffee-capsules-1-box-x-60g', 'https://shopee.co.id/product/283021328/23910388989/', 'https://www.blibli.com/p/supresso-signature-blend-coffee-capsules-nespresso-compatible/ps--INT-60044-00097', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 09:48:06');
INSERT INTO `master_produk` VALUES (144, 8, 4, NULL, NULL, NULL, 'Top 3 Bestsellers Value Set (Capsules)', 'top-3-bestsellers-value-set-capsules-20011', '20011', NULL, 'We\'re rolling out the red carpet! Our Top 3 Bestsellers Bundle features the most popular varieties of Supresso, so start here if you want to get to know us a little better. Convenient, delicious, and of great value - what\'s not to love?', 'Box', '3 Box x 60g', 136800.00, 'SUPRESSO/Top-3-Bestsellers-Bundle-capsules-1.webp', '[\"SUPRESSO/Top-3-Bestsellers-Bundle-capsules-2.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-capsules-3.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-capsules-4.webp\"]', 1, NULL, NULL, 'Top-3-Bestsellers-Value-Set-(Capsules)-3-Box-x-60g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:54');
INSERT INTO `master_produk` VALUES (145, 8, 4, NULL, NULL, NULL, 'Top 5 Bestsellers Value Set (Capsules)', 'top-5-bestsellers-value-set-capsules-20026', '20026', NULL, 'Is the Top 3 not enough? Fret not; we have the Top 5 too! Our Top 5 Bestsellers Bundle, like its namesake, includes five of our best-selling variants from us. Be your own barista with this bundle, which includes a different variety, for your every day and every week.', 'Box', '5 Box x 60g', 232800.00, 'SUPRESSO/Top-5-Bestsellers-Bundle-capsules-1.webp', '[\"SUPRESSO/Top-5-Bestsellers-Bundle-capsules-2.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-capsules-3.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-capsules-4.webp\"]', 1, NULL, NULL, 'Top-5-Bestsellers-Value-Set-(Capsules)-5-Box-x-60g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:54');
INSERT INTO `master_produk` VALUES (146, 8, 4, 1, 1, 8, 'Supresso Aceh Gayo Coffee Capsules', 'supresso-aceh-gayo-coffee-capsules-sup011c', 'SUP011C', 'Nuansa rempah - Karamel & Cokelat - Buah segar - Natural', 'Aceh Gayo coffee is often used in most coffee shops commonly for cafe latte. It has light earthy notes with a mild body and bittersweet spicy chocolate taste. Soft in acidity, this coffee reveals some elegant caramel-fruity flavours, marrying a perfect combination of spicy and sweet. Its unique taste will make you crave for more.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774406622_p_supresso-aceh-gayo-coffee-capsules-sup011c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so012_aceh_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so013_aceh_1ks.webp\"]', 0, '2025-10-09 14:58:23', 'https://indracostore.com/product/Supresso-Aceh-Gayo-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Aceh-Gayo-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/7341939013/', 'https://www.blibli.com/p/supresso-aceh-gayo-coffee-capsules-nespresso-compatible/ps--INT-60044-00056', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:25:48');
INSERT INTO `master_produk` VALUES (147, 8, 4, NULL, NULL, 14, 'Supresso Bali Kintamani Coffee Capsules', 'supresso-bali-kintamani-coffee-capsules-sup009c', 'SUP009C', 'Rasa seimbang - Nuansa manis - Citrus segar', 'Grown in the highlands of Kintamani, this coffee has unique characteristics derived from wet processing method, making them slightly sweeter. The mild body of the coffee exudes a clean light and refreshing taste exhibiting a citrusy, fruity finish. It is a must-try for those who do not like the bitter taste.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774408085_p_supresso-bali-kintamani-coffee-capsules-sup009c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so042_bali_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so043_bali_1ks.webp\"]', 0, '2025-10-09 14:57:56', 'https://indracostore.com/product/Supresso-Bali-Kintamani-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Bali-Kintamani-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/5241935759/', 'https://www.blibli.com/p/supresso-bali-kintamani-coffee-capsules-nespresso-compatible/ps--INT-60044-00054', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:31:36');
INSERT INTO `master_produk` VALUES (148, 8, 4, NULL, NULL, 15, 'Supresso Flores Bajawa Coffee Capsules', 'supresso-flores-bajawa-coffee-capsules-sup010c', 'SUP010C', 'Cokelat yang lembut - Manis sari bunga - Nuansa vanilla - Karamel', 'This 100% Arabica coffee is limited in availability and one of the most popular coffees in the globe for its strongly aromatic flavour. Akin to its name, Flores coffee has an outstanding and intense floral nectareous sweetness and fragrance with hints of vanilla and chocolate fudge, leaving a lingering caramel finish.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774408235_p_supresso-flores-bajawa-coffee-capsules-sup010c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so052_flores_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so053_flores_1ks.webp\"]', 0, '2025-10-09 14:57:26', 'https://indracostore.com/product/Supresso-Flores-Bajawa-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Flores-Bajawa-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/4941940450/', 'https://www.blibli.com/p/supresso-flores-bajawa-coffee-capsules-nespresso-compatible/ps--INT-60044-00055', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:32:16');
INSERT INTO `master_produk` VALUES (149, 8, 4, NULL, NULL, 13, 'Supresso Java Coffee Capsules', 'supresso-java-coffee-capsules-sup004c', 'SUP004C', 'Manis - Malt yang kuat - Nuansa tembakau', 'Supresso Java Robusta coffee beans are thoroughly wet-processed, kicking off the acidity, drops the body and reduces the earthiness of the cup to a unique sweetness. Its strong malty taste with hints of tobacco notes will give a perfect combination when added with cocoa - great for brewing your delicious mocha.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774407952_p_supresso-java-coffee-capsules-sup004c.png', '[\"SUPRESSO/CAPSULES-JAVA-(2).webp\", \"SUPRESSO/CAPSULES-JAVA-(3).webp\"]', 0, '2025-10-09 14:57:03', NULL, 'Supresso-Java-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/5041934197/', 'https://www.blibli.com/p/supresso-java-coffee-capsules-nespresso-compatible/ps--INT-60044-00084', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:39:55');
INSERT INTO `master_produk` VALUES (150, 8, 4, NULL, NULL, 10, 'Supresso Lampung Coffee Capsules', 'supresso-lampung-coffee-capsules-sup006c', 'SUP006C', 'Nuansa cokelat - Natural - Sentuhan rasa tembakau', 'Well-sought after by the world\'s coffee industry, this Robusta coffee gives off an immense strong-bodied bitter taste with the essence of chocolate, slightly earthy aroma and tobacco undertones. The absence of acidity is Lampung\'s trademark.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774406718_p_supresso-lampung-coffee-capsules-sup006c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so032_lampung_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so033_lampung_1ks.webp\"]', 0, '2025-10-09 14:56:41', 'https://indracostore.com/product/Supresso-Lampung-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Lampung-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/4741935560/', 'https://www.blibli.com/p/supresso-lampung-coffee-capsules-nespresso-compatible/ps--INT-60044-00053', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:27:36');
INSERT INTO `master_produk` VALUES (151, 8, 4, NULL, NULL, 28, 'Supresso Luwak Prestige Arabica Coffee Capsules', 'supresso-luwak-prestige-arabica-coffee-capsules-sup002c', 'SUP002C', 'Karamel cokelat - Lembut dan manis - Rasa mewah', 'Characterised by its velvety and sweet chocolaty-caramel taste profile, Luwak is a rare and exotic coffee that leaves every coffee lover intrigued and typically found on bucket lists around the world. A perfect cup for you if you like your coffee smooth with a clean aftertaste.', 'Box', '10 Capsules x 6g', 229500.00, 'images/uploads/1774422453_p_supresso-luwak-prestige-arabica-coffee-capsules-sup002c.webp', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_tc012_lwk_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_tc013_lwk_1ks.webp\"]', 0, '2025-10-08 15:24:06', 'https://indracostore.com/product/Supresso-Luwak-Prestige-Arabica-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Luwak-Prestige-Arabica-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/3442033247/', 'https://www.blibli.com/p/supresso-luwak-prestige-arabica-coffee-capsules-nespresso-compatible/ps--INT-60044-00061', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:22:45');
INSERT INTO `master_produk` VALUES (152, 8, 4, NULL, NULL, 11, 'Supresso Manglayang Coffee Capsules', 'supresso-manglayang-coffee-capsules-sup015c', 'SUP015C', 'Sirop maple - Buah segar - Plum asam', 'Famous for its traditional coffee cultivation that retains its original character and distinctive flavours, our Manglayang Arabica coffee provides a smooth, medium body. The gentle plum acidity flavour it exudes, complements its sweet maple syrup notes, leaving a fruity lingering mouthfeel.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774407672_p_supresso-manglayang-coffee-capsules-sup015c.png', '[\"SUPRESSO/CAPSULES-MANGLAYANG-(2).webp\", \"SUPRESSO/CAPSULES-MANGLAYANG-(3).webp\"]', 0, '2025-10-09 14:54:52', NULL, 'Supresso-Manglayang-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/6841939629/', 'https://www.blibli.com/p/supresso-manglayang-coffee-capsules-nespresso-compatible/ps--INT-60044-00059', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:00');
INSERT INTO `master_produk` VALUES (153, 8, 4, NULL, NULL, 27, 'Supresso Peaberry Coffee Capsules', 'supresso-peaberry-coffee-capsules-sup012c', 'SUP012C', 'Herbal - Buah segar - Rasa manis hingga akhir', 'Peaberry is known to be significantly sweeter than other beans because of its exclusive access to the fruit. With delicate fruity fragrance, as well as subtle nutty and herbal character, the medium acidity enveloped in sweetness carries through into the long finish.', 'Box', '10 Capsules x 6g', 114800.00, 'images/uploads/1774420921_p_supresso-peaberry-coffee-capsules-sup012c.webp', '[\"SUPRESSO/CAPSULES-PEA-(2).webp\", \"SUPRESSO/CAPSULES-PEA-(3).webp\"]', 0, '2024-12-06 18:08:21', NULL, 'Supresso-Peaberry-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/7541934799/', 'https://www.blibli.com/p/supresso-peaberry-coffee-capsules/ps--INT-60044-00057', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:00');
INSERT INTO `master_produk` VALUES (154, 8, 4, NULL, NULL, 9, 'Supresso Sumatra Mandheling Coffee Capsules', 'supresso-sumatra-mandheling-coffee-capsules-sup005c', 'SUP005C', 'Sensasi segar - Manis berempah - Natural', 'These Arabica coffee beans are not only rare and rich in history but also one of the highly recognised by gourmet coffee producers in the world. The syrupy, full body of Sumatra Mandheling, combined with its muted acidity, makes an elegant, smooth cup of coffee. A blend of sweet and spicy, exuding an exotic flavour.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774406347_p_supresso-sumatra-mandheling-coffee-capsules-sup005c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so022_sum_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so023_sum_1ks.webp\"]', 0, '2025-10-09 14:54:20', 'https://indracostore.com/product/Supresso-Sumatra-Mandheling-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Sumatra-Mandheling-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/4941939496/', 'https://www.blibli.com/p/supresso-sumatra-mandheling-coffee-capsules-nespresso-compatible/ps--INT-60044-00052', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:26:38');
INSERT INTO `master_produk` VALUES (155, 8, 4, NULL, NULL, 16, 'Supresso Toraja Kalosi Coffee Capsules', 'supresso-toraja-kalosi-coffee-capsules-sup014c', 'SUP014C', 'Rempah hangat - Sentuhan rasa manis dan lembut', 'Our Supresso Toraja Kalosi is highly valued among Japan\'s coffee drinkers because of its quality traditional processing, offering multiple layers of flavours that reveal something upon each sip. The heavy-bodied coffee is low in acidity, and its delicate aroma denotes warm spices with a sweet and smooth aftertaste.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774408329_p_supresso-toraja-kalosi-coffee-capsules-sup014c.png', '[\"SUPRESSO/250115_supresso_caps_box_sis_mp_so062_toraja_1ks.webp\", \"SUPRESSO/250115_supresso_caps_box_sis_mp_so063_toraja_1ks.webp\"]', 0, '2025-10-09 14:53:58', 'https://indracostore.com/product/Supresso-Toraja-Kalosi-Coffee-Capsules-10-Capsules-x-6g', 'Supresso-Toraja-Kalosi-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/6741934922/', 'https://www.blibli.com/p/supresso-toraja-kalosi-coffee-capsules-nespresso-compatible/ps--INT-60044-00058', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:32:59');
INSERT INTO `master_produk` VALUES (156, 8, 4, NULL, NULL, 12, 'Supresso West Java Coffee Capsules', 'supresso-west-java-coffee-capsules-sup016c', 'SUP016C', 'Rasa anggur - Buah beri - Madu manis', 'West Java coffees\' sour flavour is not too dominant yet not too earthy. They have a berry-like, wine taste with a sweet honey aroma that taste great on their own or paired well with dark chocolate desserts that accentuates its flavour. To bring out its earthiness, enjoy it with a hearty brunch made with cheese, mushrooms or bacon.', 'Box', '10 Capsules x 6g', 105300.00, 'images/uploads/1774407775_p_supresso-west-java-coffee-capsules-sup016c.png', '[\"SUPRESSO/CAPSULES-WEST-JAVA-(2).webp\", \"SUPRESSO/CAPSULES-WEST-JAVA-(3).webp\"]', 0, '2025-10-09 14:53:34', '', 'Supresso-West-Java-Coffee-Capsules-10-Capsules-x-6g', 'https://shopee.co.id/product/283021328/6741939887/', 'https://www.blibli.com/p/supresso-west-java-coffee-capsules-nespresso-compatible/ps--INT-60044-00060', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:03');
INSERT INTO `master_produk` VALUES (157, 8, 4, NULL, NULL, NULL, 'Supresso Arabica Value Set (Drip)', 'supresso-arabica-value-set-drip-20009', '20009', NULL, 'This Arabica Bundle is truly the creme de la creme, where all variants are 100% Arabica and of Single Origin, perfect for those of us who rely on caffeine to get through the day. Its the perfect sampling of sweet and refreshing, that is sure to open your mind and taste buds to a whole new world of coffee.', 'Box', '3 Box x 50g', 107300.00, 'SUPRESSO/Arabica-Bundle-drip-1.webp', '[\"SUPRESSO/Arabica-Bundle-drip-2.webp\", \"SUPRESSO/Arabica-Bundle-drip-3.webp\", \"SUPRESSO/Arabica-Bundle-drip-4.webp\"]', 1, NULL, NULL, 'Supresso-Arabica-Value-Set-(Drip)-3-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:03');
INSERT INTO `master_produk` VALUES (158, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Arabica Gold Drip Coffee', 'supresso-balicafe-arabica-gold-drip-coffee-10332', '10332', 'Herbal - Aroma kuat - Sensasi sitrus', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen arabica Bali coffee beans and with a full city roasting method so that it produces fragrant arabica coffee with a Balinese coffee taste.', 'Box', '5 Sachets x 10g', 61100.00, 'images/uploads/1774409117_p_BaliCafe-Arabica-Gold-Drip-Coffee-50g.png', '[\"SUPRESSO/76-BaliCafe-Arabica-Gold-Drip-Coffee-2.webp\", \"SUPRESSO/76-BaliCafe-Arabica-Gold-Drip-Coffee-3.webp\"]', 0, '2024-03-21 09:36:56', 'https://indracostore.com/product/Supresso-BaliCafe-Arabica-Gold-Drip-Coffee-5-Sachets-x-10g', 'Supresso-BaliCafe-Arabica-Gold-Drip-Coffee-5-Sachets-x-10g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 16:02:31');
INSERT INTO `master_produk` VALUES (159, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Peaberry Robusta Drip Coffee', 'supresso-balicafe-peaberry-robusta-drip-coffee-10339', '10339', 'Sensasi rasa cokelat karamel - Rasa natural Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen peaberry robusta Bali coffee beans and with a full city+ roasting method so that it produces fragrant peaberry robusta coffee with a Balinese coffee taste.', 'Box', '5 Sachets x 10g', 56600.00, 'images/uploads/1774409079_p_BaliCafe-Peaberry-Robusta-Drip-Coffee-50g.png', '[\"SUPRESSO/80-BaliCafe-Peaberry-Robusta-Drip-Coffee-2.webp\", \"SUPRESSO/80-BaliCafe-Peaberry-Robusta-Drip-Coffee-3.webp\"]', 0, '2024-03-21 10:01:55', 'https://indracostore.com/product/Supresso-BaliCafe-Peaberry-Robusta-Drip-Coffee-5-Sachets-x-10g', 'Supresso-BaliCafe-Peaberry-Robusta-Drip-Coffee-5-Sachets-x-10g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:20:05');
INSERT INTO `master_produk` VALUES (160, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Robusta Drip Coffee', 'supresso-balicafe-robusta-drip-coffee-10344', '10344', 'Sensasi rasa cokelat - Agak manis - Rasa natural Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen robusta Bali coffee beans and with a full city roasting method so that it produces fragrant robusta coffee with a Balinese coffee taste.', 'Box', '5 Sachets x 10g', 48100.00, 'images/uploads/1774409046_p_BaliCafe-Robusta-Drip-Coffee-50g.png', '[\"SUPRESSO/79-BaliCafe-Robusta-Drip-Coffee-2.webp\", \"SUPRESSO/79-BaliCafe-Robusta-Drip-Coffee-3.webp\"]', 0, '2024-03-21 09:55:03', 'https://indracostore.com/product/Supresso-BaliCafe-Robusta-Drip-Coffee-5-Sachets-x-10g', 'Supresso-BaliCafe-Robusta-Drip-Coffee-5-Sachets-x-10g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 16:01:28');
INSERT INTO `master_produk` VALUES (161, 9, 5, NULL, NULL, NULL, 'Supresso BaliCafe Sunset Blend Drip Coffee', 'supresso-balicafe-sunset-blend-drip-coffee-10349', '10349', 'Sensasi sitrus & manis - Herbal segar - Rasa rempah Bali', 'Balinese coffee, through and through. Created with pure Balinese coffee, discover our coffee creations, and delve into the eternal, and mythical island of Bali with us. Processed from chosen and blended arabica - robusta Bali coffee beans and with a full city roasting method so that it produces fragrant robusta coffee with a Balinese coffee taste.', 'Box', '5 Sachets x 10g', 58500.00, 'images/uploads/1774409000_p_BaliCafe-Sunset-Blend-Drip-Coffee-50g.png', '[\"SUPRESSO/83-BaliCafe-Sunset-Blend-Drip-Coffee-2.webp\", \"SUPRESSO/83-BaliCafe-Sunset-Blend-Drip-Coffee-3.webp\"]', 0, '2024-03-21 10:07:10', 'https://indracostore.com/product/Supresso-BaliCafe-Sunset-Blend-Drip-Coffee-5-Sachets-x-10g', 'Supresso-BaliCafe-Sunset-Blend-Drip-Coffee-5-Sachets-x-10g', '', '', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 16:01:05');
INSERT INTO `master_produk` VALUES (162, 8, 4, NULL, NULL, NULL, 'Supresso Free Lampung Drip Coffee', 'supresso-free-lampung-drip-coffee-sup006d', 'SUP006D', 'Nuansa cokelat - Natural - Sentuhan rasa tembakau', '', 'Box', '', 0.00, '', NULL, 1, '', '', '', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-25 15:27:59');
INSERT INTO `master_produk` VALUES (163, 8, 4, NULL, NULL, NULL, 'Supresso Java Value Set (Drip)', 'supresso-java-value-set-drip-20003', '20003', '', 'Want to know the taste of Java? Its all in this bundle, which brings together: Java and West Java. Each variety contains two distinct flavours - \"West Java\" represents a heavier body while \"Java\" is uniquely malty, sweet and has a slightly lighter body.', 'Box', '2 Box x 50g', 58000.00, 'images/uploads/1774413986_p_supresso-java-value-set-drip-20003.jpg', '[\"SUPRESSO/Java-Bundle-coffee-drip-2.webp\", \"SUPRESSO/Java-Bundle-coffee-drip-3.webp\", \"SUPRESSO/Java-Bundle-coffee-drip-4.webp\"]', 1, '', '', 'Supresso-Java-Value-Set-(Drip)-2-Box-x-50g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (164, 8, 4, NULL, NULL, NULL, 'Supresso Luwak Twin Value Set (Drip)', 'supresso-luwak-twin-value-set-drip-20020', '20020', NULL, 'You know it, you love it. Chocolaty, warm, and inviting; what more can one want? Double up on your favourite Luwak Prestige Drip with the Luwak Twin Bundle for a reduced price.', 'Box', '2 Box x 50g', 285000.00, 'images/uploads/1774421524_p_supresso-luwak-twin-value-set-drip-20020.webp', '[\"SUPRESSO/69-Luwak-Twin-Bundle-(Drip)-2.webp\", \"SUPRESSO/69-Luwak-Twin-Bundle-(Drip)-3.webp\", \"SUPRESSO/69-Luwak-Twin-Bundle-(Drip)-4.webp\"]', 1, NULL, NULL, 'Supresso-Luwak-Twin-Value-Set-(Drip)-2-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (165, 8, 4, NULL, NULL, NULL, 'Supresso Robusta Value Set (Drip)', 'supresso-robusta-value-set-drip-20006', '20006', NULL, 'Like your Indonesian pour-overs strong and robust? The Robusta bundle consisting of only Single Origin Robusta coffee, is guaranteed to knock you off your feet and keep you alert through your afternoon workday.', 'Box', '3 Box x 50g', 85000.00, 'SUPRESSO/Robusta-Bundle-drip-1.webp', '[\"SUPRESSO/Robusta-Bundle-drip-2.webp\", \"SUPRESSO/Robusta-Bundle-drip-3.webp\", \"SUPRESSO/Robusta-Bundle-drip-4.webp\"]', 1, NULL, NULL, 'Supresso-Robusta-Value-Set-(Drip)-3-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (166, 8, 4, NULL, NULL, NULL, 'Top 3 Bestsellers Value Set (Drip)', 'top-3-bestsellers-value-set-drip-20012', '20012', NULL, 'We\'re rolling out the red carpet! Our Top 3 Bestsellers Bundle features the most popular varieties of Supresso, so start here if you want to get to know us a little better. Convenient, delicious, and of great value - what\'s not to love?', 'Box', '3 Box x 50g', 95500.00, 'SUPRESSO/Top-3-Bestsellers-Bundle-drip-1.webp', '[\"SUPRESSO/Top-3-Bestsellers-Bundle-drip-2.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-drip-3.webp\", \"SUPRESSO/Top-3-Bestsellers-Bundle-drip-4.webp\"]', 1, NULL, NULL, 'Top-3-Bestsellers-Value-Set-(Drip)-3-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (167, 8, 4, NULL, NULL, NULL, 'Top 5 Bestsellers Value Set (Drip)', 'top-5-bestsellers-value-set-drip-20027', '20027', NULL, 'Is the Top 3 not enough? Fret not; we have the Top 5 too! Our Top 5 Bestsellers Bundle, like its namesake, includes five of our best-selling variants from us. Be your own barista with this bundle, which includes a different variety, for your every day and every week.', 'Box', '5 Box x 50g', 168000.00, 'SUPRESSO/Top-5-Bestsellers-Bundle-drip-1.webp', '[\"SUPRESSO/Top-5-Bestsellers-Bundle-drip-2.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-drip-3.webp\", \"SUPRESSO/Top-5-Bestsellers-Bundle-drip-4.webp\"]', 1, NULL, NULL, 'Top-5-Bestsellers-Value-Set-(Drip)-5-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (168, 8, 4, NULL, NULL, NULL, 'World Blend Collection Value Set', 'world-blend-collection-value-set-20022', '20022', NULL, 'Keen to journey through parts of the world with us? Our World Blend Collection includes the Brazilia Blend, Costa Rica Blend and Nanyang Coffee, bringing together a unity of spirit, taste, and characteristics of different coffee beans from various regions all around the world, into one bundle.', 'Box', '3 Box x 50g', 103600.00, 'SUPRESSO/71-World-Blend-Collection-Bundle-1.webp', '[\"SUPRESSO/71-World-Blend-Collection-Bundle-2.webp\", \"SUPRESSO/71-World-Blend-Collection-Bundle-3.webp\", \"SUPRESSO/71-World-Blend-Collection-Bundle-4.webp\"]', 1, NULL, NULL, 'World-Blend-Collection-Value-Set-3-Box-x-50g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:09');
INSERT INTO `master_produk` VALUES (169, 8, 4, 1, 1, 8, 'Supresso Aceh Gayo Drip Coffee', 'supresso-aceh-gayo-drip-coffee-sup011d', 'SUP011D', 'Nuansa rempah - Karamel & Cokelat - Buah segar - Natural', 'Aceh Gayo coffee is often used in most coffee shops commonly for cafe latte. It has light earthy notes with a mild body and bittersweet spicy chocolate taste. Soft in acidity, this coffee reveals some elegant caramel-fruity flavours, marrying a perfect combination of spicy and sweet. Its unique taste will make you crave for more.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426222_p_supresso-aceh-gayo-drip-coffee-sup011d.png', '[\"SUPRESSO/Aceh-Gayo-Coffee-drip-50-2.webp\", \"SUPRESSO/Aceh-Gayo-Coffee-drip-50-3.webp\"]', 0, '2024-11-07 08:26:26', 'https://indracostore.com/product/Supresso-Aceh-Gayo-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Aceh-Gayo-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/5341628864/', 'https://www.blibli.com/p/supresso-aceh-gayo-coffee-beans/ps--INT-60044-00022', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:25:45');
INSERT INTO `master_produk` VALUES (170, 8, 4, NULL, NULL, 14, 'Supresso Bali Kintamani Drip Coffee', 'supresso-bali-kintamani-drip-coffee-sup009d', 'SUP009D', 'Rasa seimbang - Nuansa manis - Citrus segar', 'Grown in the highlands of Kintamani, this coffee has unique characteristics derived from wet processing method, making them slightly sweeter. The mild body of the coffee exudes a clean light and refreshing taste exhibiting a citrusy, fruity finish. It is a must-try for those who do not like the bitter taste.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426240_p_supresso-bali-kintamani-drip-coffee-sup009d.png', '[\"SUPRESSO/DRIP-BALI-2.webp\", \"SUPRESSO/DRIP-BALI-3.webp\"]', 0, '2024-11-07 08:30:57', 'https://indracostore.com/product/Supresso-Bali-Kintamani-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Bali-Kintamani-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/6541624175/', 'https://www.blibli.com/p/supresso-bali-kintamani-drip-coffee/ps--INT-60044-00038', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:31:42');
INSERT INTO `master_produk` VALUES (171, 8, 4, NULL, NULL, 33, 'Supresso Brazilia Blend Drip Coffee', 'supresso-brazilia-blend-drip-coffee-sup017d', 'SUP017D', 'Rasa biji kopi yang kuat - Nuansa buah beri - Cokelat', 'Intense nuttiness, low acidity and hints of berry-like flavour that offers an excellent bittersweet chocolate taste, our Brazilia Blend drip coffee is not only perfect on its own. It is also an excellent base for brewing flavoured coffees and cappuccino.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426498_p_supresso-brazilia-blend-drip-coffee-sup017d.png', '[\"SUPRESSO/50-brazilia-blend-drip--coffee-2.webp\", \"SUPRESSO/50-brazilia-blend-drip--coffee-3.webp\"]', 0, '2024-11-07 08:31:34', 'https://indracostore.com/product/Supresso-Brazilia-Blend-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Brazilia-Blend-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/7741641637/', 'https://www.blibli.com/p/supresso-brazilia-blend-drip-coffee/ps--INT-60044-00045', 'active', 0, '2026-03-17 15:07:41', '2026-05-12 08:06:03');
INSERT INTO `master_produk` VALUES (172, 8, 4, NULL, NULL, 32, 'Supresso Costa Rica Blend Drip Coffee', 'supresso-costa-rica-blend-drip-coffee-sup018d', 'SUP018D', 'Nuansa apel merah - Almond - Hazelnut', 'Costa Rican coffees believed to have some of the best coffee flavour profiles in the south and central America. Our medium-bodied drip coffee has a defining hazelnut and almond taste with hints of red apple tones and subtle acidity. Your savoury, hearty breakfast will be a good pairing with our blend.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426522_p_supresso-costa-rica-blend-drip-coffee-sup018d.png', '[\"SUPRESSO/49-costa-rica-blend-drip-coffee-2.webp\", \"SUPRESSO/49-costa-rica-blend-drip-coffee-3.webp\"]', 0, '2024-11-07 08:32:06', 'https://indracostore.com/product/Supresso-Costa-Rica-Blend-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Costa-Rica-Blend-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/3841735203/', 'https://www.blibli.com/p/supresso-costa-rica-blend-drip-coffee/ps--INT-60044-00046', 'active', 0, '2026-03-17 15:07:41', '2026-05-12 08:05:58');
INSERT INTO `master_produk` VALUES (173, 8, 4, NULL, NULL, 15, 'Supresso Flores Bajawa Drip Coffee', 'supresso-flores-bajawa-drip-coffee-sup010d', 'SUP010D', 'Cokelat yang lembut - Manis sari bunga - Nuansa vanilla - Karamel', 'This 100% Arabica coffee is limited in availability and one of the most popular coffees in the globe for its strongly aromatic flavour. Akin to its name, Flores coffee has an outstanding and intense floral nectareous sweetness and fragrance with hints of vanilla and chocolate fudge, leaving a lingering caramel finish.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426259_p_supresso-flores-bajawa-drip-coffee-sup010d.png', '[\"SUPRESSO/DRIP-flores-2.webp\", \"SUPRESSO/DRIP-flores-3.webp\"]', 0, '2024-11-07 08:32:37', 'https://indracostore.com/product/Supresso-Flores-Bajawa-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Flores-Bajawa-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/5741625727/', 'https://www.blibli.com/p/supresso-flores-bajawa-drip-coffee/ps--INT-60044-00039', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:32:21');
INSERT INTO `master_produk` VALUES (174, 8, 4, NULL, NULL, 13, 'Supresso Java Drip Coffee', 'supresso-java-drip-coffee-sup004d', 'SUP004D', 'Manis - Malt yang kuat - Nuansa tembakau', 'Supresso Java Robusta coffee beans are thoroughly wet-processed, kicking off the acidity, drops the body and reduces the earthiness of the cup to a unique sweetness. Its strong malty taste with hints of tobacco notes will give a perfect combination when added with cocoa - great for brewing your delicious mocha.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426279_p_supresso-java-drip-coffee-sup004d.png', '[\"SUPRESSO/DRIP-java-2.webp\", \"SUPRESSO/DRIP-java-3.webp\"]', 0, '2024-11-07 08:33:11', 'https://indracostore.com/product/Supresso-Java-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Java-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/4841619056/', 'https://www.blibli.com/p/supresso-java-drip-coffee/ps--INT-60044-00035', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:30:56');
INSERT INTO `master_produk` VALUES (175, 8, 4, NULL, NULL, 10, 'Supresso Lampung Drip Coffee', 'supresso-lampung-drip-coffee-sup006d', 'SUP006D', 'Nuansa cokelat - Natural - Sentuhan rasa tembakau', 'Well-sought after by the world\'s coffee industry, this Robusta coffee gives off an immense strong-bodied bitter taste with the essence of chocolate, slightly earthy aroma and tobacco undertones. The absence of acidity is Lampung\'s trademark.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426318_p_supresso-lampung-drip-coffee-sup006d.png', '[\"SUPRESSO/DRIP-LAMPUNG-2.webp\", \"SUPRESSO/DRIP-LAMPUNG-3.webp\"]', 1, '2024-11-07 08:34:43', 'https://indracostore.com/product/Supresso-Lampung-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Lampung-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/5341629533/', 'https://www.blibli.com/p/supresso-lampung-drip-coffee/ps--INT-60044-00037', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:28:01');
INSERT INTO `master_produk` VALUES (176, 8, 4, NULL, NULL, 28, 'Supresso Luwak Prestige Arabica Drip Coffee', 'supresso-luwak-prestige-arabica-drip-coffee-sup002d', 'SUP002D', 'Karamel cokelat - Lembut dan manis - Rasa mewah', 'Characterised by its velvety and sweet chocolaty-caramel taste profile, Luwak is a rare and exotic coffee that leaves every coffee lover intrigued and typically found on bucket lists around the world. A perfect cup for you if you like your coffee smooth with a clean aftertaste.', 'Box', '5 Sachets x 10g', 216000.00, 'images/uploads/1774426441_p_supresso-luwak-prestige-arabica-drip-coffee-sup002d.png', '[\"SUPRESSO/DRIP-LUWAK-2.webp\", \"SUPRESSO/DRIP-LUWAK-3.webp\"]', 0, '2024-11-07 08:36:02', 'https://indracostore.com/product/Supresso-Luwak-Prestige-Arabica-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Luwak-Prestige-Arabica-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/6450356674/', 'https://www.blibli.com/p/supresso-luwak-prestige-arabica-drip-coffee/ps--INT-60044-00048', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:22:48');
INSERT INTO `master_produk` VALUES (177, 8, 4, NULL, NULL, 11, 'Supresso Manglayang Drip Coffee', 'supresso-manglayang-drip-coffee-sup015d', 'SUP015D', 'Sirop maple - Buah segar - Plum asam', 'Famous for its traditional coffee cultivation that retains its original character and distinctive flavours, our Manglayang Arabica coffee provides a smooth, medium body. The gentle plum acidity flavour it exudes, complements its sweet maple syrup notes, leaving a fruity lingering mouthfeel.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426341_p_supresso-manglayang-drip-coffee-sup015d.png', '[\"SUPRESSO/DRIP-MANGLA-2.webp\", \"SUPRESSO/DRIP-MANGLA-3.webp\"]', 0, '2024-11-07 08:36:37', 'https://indracostore.com/product/Supresso-Manglayang-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Manglayang-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/5241636649/', 'https://www.blibli.com/p/supresso-manglayang-drip-coffee/ps--INT-60044-00043', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:28:58');
INSERT INTO `master_produk` VALUES (178, 8, 4, NULL, NULL, 34, 'Supresso Nanyang Drip Coffee', 'supresso-nanyang-drip-coffee-sup019d', 'SUP019D', 's', 'Our Nanyang Coffee is a favourite of the older generation due to its traditional old-school flavour that delights your palate with every sip reminding you of home. It has a rich and robust aroma that exudes a gentle, bittersweet taste, best paired with your morning kaya or peanut butter toast and half-boiled eggs.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426552_p_supresso-nanyang-drip-coffee-sup019d.png', '[\"SUPRESSO/86-Nanyang-Coffee-Drip-Coffee-2.webp\", \"SUPRESSO/86-Nanyang-Coffee-Drip-Coffee-3.webp\"]', 0, '2024-11-07 08:37:11', 'https://indracostore.com/product/Supresso-Nanyang-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Nanyang-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/4841644329/', 'https://www.blibli.com/p/supresso-nanyang-coffee-drip/ps--INT-60044-00047', 'active', 0, '2026-03-17 15:07:41', '2026-05-12 08:05:26');
INSERT INTO `master_produk` VALUES (179, 8, 4, NULL, NULL, 27, 'Supresso Peaberry Drip Coffee', 'supresso-peaberry-drip-coffee-sup012d', 'SUP012D', 'Herbal - Buah segar - Rasa manis hingga akhir', 'Peaberry is known to be significantly sweeter than other beans because of its exclusive access to the fruit. With delicate fruity fragrance, as well as subtle nutty and herbal character, the medium acidity enveloped in sweetness carries through into the long finish.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426459_p_supresso-peaberry-drip-coffee-sup012d.png', '[\"SUPRESSO/DRIP-PEA-2.webp\", \"SUPRESSO/DRIP-PEA-3.webp\"]', 0, '2024-11-07 08:37:43', 'https://indracostore.com/product/Supresso-Peaberry-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Peaberry-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/3741729836/', 'https://www.blibli.com/p/supresso-peaberry-drip-coffee/ps--INT-60044-00041', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:18:58');
INSERT INTO `master_produk` VALUES (180, 8, 4, NULL, NULL, 9, 'Supresso Sumatra Mandheling Drip Coffee', 'supresso-sumatra-mandheling-drip-coffee-sup005d', 'SUP005D', 'Sensasi segar - Manis berempah - Natural', 'These Arabica coffee beans are not only rare and rich in history but also one of the highly recognised by gourmet coffee producers in the world. The syrupy, full body of Sumatra Mandheling, combined with its muted acidity, makes an elegant, smooth cup of coffee. A blend of sweet and spicy, exuding an exotic flavour.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426363_p_supresso-sumatra-mandheling-drip-coffee-sup005d.png', '[\"SUPRESSO/DRIP-SUM-2.webp\", \"SUPRESSO/DRIP-SUM-3.webp\"]', 0, '2024-11-07 08:38:20', 'https://indracostore.com/product/Supresso-Sumatra-Mandheling-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Sumatra-Mandheling-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/4941624638/', 'https://www.blibli.com/p/supresso-sumatra-mandheling-drip-coffee/ps--INT-60044-00036', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:26:51');
INSERT INTO `master_produk` VALUES (181, 8, 4, NULL, NULL, 16, 'Supresso Toraja Kalosi Drip Coffee', 'supresso-toraja-kalosi-drip-coffee-sup014d', 'SUP014D', 'Rempah hangat - Sentuhan rasa manis dan lembut', 'Our Supresso Toraja Kalosi is highly valued among Japan\'s coffee drinkers because of its quality traditional processing, offering multiple layers of flavours that reveal something upon each sip. The heavy-bodied coffee is low in acidity, and its delicate aroma denotes warm spices with a sweet and smooth aftertaste.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426387_p_supresso-toraja-kalosi-drip-coffee-sup014d.png', '[\"SUPRESSO/DRIP-TORA-2.webp\", \"SUPRESSO/DRIP-TORA-3.webp\"]', 0, '2024-11-07 08:38:48', 'https://indracostore.com/product/Supresso-Toraja-Kalosi-Drip-Coffee-5-Sachets-x-10g', 'Supresso-Toraja-Kalosi-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/3741731763/', 'https://www.blibli.com/p/supresso-toraja-kalosi-drip-coffee/ps--INT-60044-00042', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:33:07');
INSERT INTO `master_produk` VALUES (182, 8, 4, NULL, NULL, 12, 'Supresso West Java Drip Coffee', 'supresso-west-java-drip-coffee-sup016d', 'SUP016D', 'Rasa anggur - Buah beri - Madu manis', 'West Java coffees\' sour flavour is not too dominant yet not too earthy. They have a berry-like, wine taste with a sweet honey aroma that taste great on their own or paired well with dark chocolate desserts that accentuates its flavour. To bring out its earthiness, enjoy it with a hearty brunch made with cheese, mushrooms or bacon.', 'Box', '5 Sachets x 10g', 60800.00, 'images/uploads/1774426402_p_supresso-west-java-drip-coffee-sup016d.png', '[\"SUPRESSO/DRIP-WEST-2.webp\", \"SUPRESSO/DRIP-WEST-3.webp\"]', 0, '2024-11-07 09:02:16', 'https://indracostore.com/product/Supresso-West-Java-Drip-Coffee-5-Sachets-x-10g', 'Supresso-West-Java-Drip-Coffee-5-Sachets-x-10g', 'https://shopee.co.id/product/283021328/6241640055/', 'https://www.blibli.com/p/supresso-west-java-drip-coffee/ps--INT-60044-00044', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 15:30:05');
INSERT INTO `master_produk` VALUES (183, 2, 9, NULL, NULL, NULL, 'Uang Emas Kopi Bro Kopi Susu Gula Aren', 'uang-emas-kopi-bro-kopi-susu-gula-aren-uekbsga27', 'UEKBSGA27', 'Kenikmatan khas dari paduan biji kopi pilihan, susu, dan gula aren terbaik menghasilkan keseimbangan rasa Kopi BRO yang harum, nikmat, dan lebih terasa kopi susu gula arennya.', 'Kenikmatan khas dari paduan biji kopi pilihan, susu, dan gula aren terbaik menghasilkan keseimbangan rasa Kopi BRO yang harum, nikmat, dan lebih terasa kopi susu gula arennya.', 'Renceng', '10 sachets x 27g', 24800.00, 'images/uploads/1774409969_p_uang-emas-kopi-bro-kopi-susu-gula-aren-uekbsga27.png', '[\"UANGEMAS/UE_KOPIBRO-SUSU_GULA_AREN2.webp\", \"UANGEMAS/UE_KOPIBRO-SUSU_GULA_AREN3.webp\"]', 0, '2026-01-21 09:55:41', 'https://indracostore.com/product/Uang-Emas-Kopi-Bro-Kopi-Susu-Gula-Aren-10-sachets-x-27g', 'Uang-Emas-Kopi-Bro-Kopi-Susu-Gula-Aren-10-sachets-x-27g', 'https://shopee.co.id/product/283021328/25050984512/', 'https://www.blibli.com/p/uang-emas-kopi-bro-kopi-susu-gula-aren-10-sachets-x-27g/ps--INT-60044-00146', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:06:12');
INSERT INTO `master_produk` VALUES (184, 11, 12, NULL, NULL, NULL, 'intiRasa Santan Bubuk Original', 'intirasa-santan-bubuk-original-isb130', 'ISB130', 'intiRasa santan bubuk dibuat dari daging kelapa pilihan, sehingga menghasilkan santan bubuk berkualitas yang cocok untuk kebutuhan dapur anda sehari hari.', 'intiRasa santan bubuk dibuat dari daging kelapa pilihan, sehingga menghasilkan santan bubuk berkualitas yang cocok untuk kebutuhan dapur anda sehari hari.', 'Renceng', '10 sachets x 13g', 12000.00, 'images/uploads/1774411116_p_intirasa-santan-bubuk-original-isb130.webp', '[\"INTIRASA/INTIRASA_SANTAN_2.webp\", \"INTIRASA/INTIRASA_SANTAN_3.webp\"]', 0, '2025-09-15 09:08:40', 'https://indracostore.com/product/intiRasa-Santan-Bubuk-Original-10-sachets-x-13g', 'intiRasa-Santan-Bubuk-Original-10-sachets-x-13g', 'https://shopee.co.id/product/283021328/19195204923/', 'https://www.blibli.com/p/intirasa-santan-bubuk-original-10-sachets-x-13g/ps--INT-60044-00144', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:33:11');
INSERT INTO `master_produk` VALUES (185, 2, 9, NULL, NULL, NULL, 'Uang Emas Kopi Bro Kopi Gula Aren', 'uang-emas-kopi-bro-kopi-gula-aren-uekbga23', 'UEKBGA23', 'Kenikmatan khas dari paduan biji kopi pilihan, dan gula aren terbaik menghasilkan keseimbangan rasa Kopi BRO yang harum, nikmat, dan lebih terasa kopi susu gula arennya.', 'Kenikmatan khas dari paduan biji kopi pilihan, dan gula aren terbaik menghasilkan keseimbangan rasa Kopi BRO yang harum, nikmat, dan lebih terasa kopi gula arennya.', 'Renceng', '10 sachets x 23g', 19900.00, 'images/uploads/1774409919_p_uang-emas-kopi-bro-kopi-gula-aren-uekbga23.png', '[\"UANGEMAS/UE_KOPIBRO-GULA_AREN1.webp\", \"UANGEMAS/UE_KOPIBRO-GULA_AREN3.webp\"]', 0, '2026-01-21 09:56:17', 'https://indracostore.com/product/Uang-Emas-Kopi-Bro-Kopi-Gula-Aren-10-sachets-x-23g', 'Uang-Emas-Kopi-Bro-Kopi-Gula-Aren-10-sachets-x-23g', 'https://shopee.co.id/product/283021328/22060884549/', 'https://www.blibli.com/p/uang-emas-kopi-bro-kopi-gula-aren-10-sachets-x-23g/ps--INT-60044-00145', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:06:36');
INSERT INTO `master_produk` VALUES (186, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Kopi SP Bintang', 'rasa-sayang-kopi-sp-bintang-rssp60', 'RSSP60', 'Biji kopi pilihan yang diracik dengan tradisi pengolahan kopi yang khas, menghasilkan rasa kopi SP Bintang yang harum, nikmat, dan akrab untuk semua kalangan.', 'Biji kopi pilihan yang diracik dengan tradisi pengolahan kopi yang khas, menghasilkan rasa kopi SP Bintang yang harum, nikmat, dan akrab untuk semua kalangan.', 'Renceng', '10 sachets x 60g', 44600.00, 'images/uploads/1774411392_p_Rasa-Sayang-Kopi-SP-Bintang-Renceng-(10 sachets x 60g).png', '[\"RASASAYANG/RS_SP_BINTANG_2.webp\", \"RASASAYANG/RS_SP_BINTANG_3.webp\"]', 0, '2024-11-05 10:56:01', 'https://indracostore.com/product/Rasa-Sayang-Kopi-SP-Bintang-10-sachets-x-60g', 'Rasa-Sayang-Kopi-SP-Bintang-10-sachets-x-60g', 'https://shopee.co.id/product/283021328/25650969526/', 'https://www.blibli.com/p/rasa-sayang-kopi-sp-bintang-10-sachets-x-60g/ps--INT-60044-00147', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 14:26:28');
INSERT INTO `master_produk` VALUES (187, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Coffee Mix R10', 'rasa-sayang-coffee-mix-r10-rscm20', 'RSCM20', 'Perpaduan kopi instan, krimer, dan gula murni menghadirkan komposisi tepat dari segi rasa dan aroma yang pas nikmatnya.', 'Perpaduan kopi instan, krimer, dan gula murni menghadirkan komposisi tepat dari segi rasa dan aroma yang pas nikmatnya.', 'Renceng', '10 sachets x 20g', 16400.00, 'images/uploads/1774411368_p_Rasa-Sayang-Coffee-Mix-R10-Renceng-(10 sachets x 20g).png', '[\"RASASAYANG/RS_COFFEE_MIX_11.webp\", \"RASASAYANG/RS_COFFEE_MIX_2.webp\", \"RASASAYANG/RS_COFFEE_MIX_3.webp\"]', 0, '2024-03-21 11:30:59', '', 'Rasa-Sayang-Coffee-Mix-R10-10-sachets-x-20g', '', '', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:16');
INSERT INTO `master_produk` VALUES (188, 3, 7, NULL, NULL, NULL, 'Rasa Sayang All-Day Blend 200g Can', 'rasa-sayang-all-day-blend-200g-can-rsab200', 'RSAB200', 'Kopi Rasa Sayang All-Day Blend diciptakan dengan perpaduan keunikan aroma dan cita rasabiji kopi pilihan yang nikmatnya dapat dirasakan setiap saat. Rasa Sayang All-Day Blend Coffee was created with a unique combination of aroma dantaste from selected coffee beans that can be savored at any time.', 'Kopi Rasa Sayang All-Day Blend diciptakan dengan perpaduan keunikan aroma dan cita rasabiji kopi pilihan yang nikmatnya dapat dirasakan setiap saat. Rasa Sayang All-Day Blend Coffee was created with a unique combination of aroma dantaste from selected coffee beans that can be savored at any time.', 'Can', '1 Can x 200g', 62400.00, 'images/uploads/1774495470_p_rasa-sayang-all-day-blend-200g-can-rsab200.png', '[\"RASASAYANG/allday2.webp\", \"RASASAYANG/allday3.webp\"]', 0, '2026-01-21 10:01:44', 'https://indracostore.com/product/Rasa-Sayang-All-Day-Blend-200g-Can-1-Can-x-200g', 'Rasa-Sayang-All-Day-Blend-200g-Can-1-Can-x-200g', 'https://shopee.co.id/product/283021328/24901035036/', 'https://www.blibli.com/p/rasa-sayang-all-day-blend-200g-can/ps--INT-60044-00149', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 10:24:30');
INSERT INTO `master_produk` VALUES (189, 3, 7, NULL, NULL, NULL, 'Rasa Sayang Luwak Blend 200g Can', 'rasa-sayang-luwak-blend-200g-can-rslb200', 'RSLB200', 'Kopi Rasa Sayang Luwak Blend hasil perpaduan aroma dan cita rasa spesial kopi Rasa\r\nSayang dengan kopi Luwak dari Sumatra.', 'Kopi Rasa Sayang Luwak Blend hasil perpaduan aroma dan cita rasa spesial kopi Rasa\r\nSayang dengan kopi Luwak dari Sumatra.', 'Can', '1 Can x 200g', 135000.00, 'images/uploads/1774495456_p_rasa-sayang-luwak-blend-200g-can-rslb200.png', '[\"RASASAYANG/luwak2.webp\", \"RASASAYANG/luwak3.webp\"]', 0, '2024-11-05 10:56:39', 'https://indracostore.com/product/Rasa-Sayang-Luwak-Blend-200g-Can-1-Can-x-200g', 'Rasa-Sayang-Luwak-Blend-200g-Can-1-Can-x-200g', 'https://shopee.co.id/product/283021328/17699530894/', 'https://www.blibli.com/p/rasa-sayang-luwak-blend-200g-can/ps--INT-60044-00150', 'active', 0, '2026-03-17 15:07:41', '2026-03-26 10:24:16');
INSERT INTO `master_produk` VALUES (190, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs450-2', 'TBS450', 'Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Tugu Buaya Kopi Special<br><br>Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Bag', '1 Bag x 450g', 30800.00, 'images/uploads/1774412251_p_tugu-buaya-kopi-special-tbs450-2.png', '[\"TUGUBUAYA/TB-4505.png\"]', 0, '2024-01-09 14:56:05', NULL, NULL, NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-25 11:17:31');
INSERT INTO `master_produk` VALUES (191, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs160', 'TBS160', 'Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Sachet', '1 Sachet x 160g', 23000.00, 'images/uploads/1774412003_p_tugu-buaya-kopi-special-tbs160.png', '[\"TUGUBUAYA/TB_160G_2.webp\", \"TUGUBUAYA/TB_160G_3.webp\"]', 0, '2025-08-21 13:12:08', NULL, 'Tugu-Buaya-Kopi-Special-1-Bag-x-160g', 'https://shopee.co.id/product/283021328/24311947357/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-160g/ps--INT-60044-00152', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:17');
INSERT INTO `master_produk` VALUES (192, 2, 9, NULL, NULL, NULL, 'Uang Emas Kopi Special', 'uang-emas-kopi-special-ues7', 'UES7', 'Uang Emas Kopi Special<br><br>Kami mengolah Uang Emas Kopi Special dari biji kopi pilihan. Melalui kontrol kualitas yang ketat dan proses pengemasan yg higienis menghasilkan kopi dengan kenikmatan tiada tara.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sachet kopi ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap untuk dinikmati.', 'Uang Emas Kopi Special<br><br>Kami mengolah Uang Emas Kopi Special dari biji kopi pilihan. Melalui kontrol kualitas yang ketat dan proses pengemasan yg higienis menghasilkan kopi dengan kenikmatan tiada tara.<br><br>\r\nSaran Penyajian:<br>Masukkan satu sachet kopi ke dalam cangkir dan tambahkan gula secukupnya sesuai dengan selera Anda. Tuangkan air panas ±200ml ke dalamnya, aduk rata dan kopi siap untuk dinikmati.', 'Bag', '10 sachets x 7g', 8100.00, 'images/uploads/1774410259_p_UE_350_1.png', '[\"UANGEMAS/UE_7G_2.webp\\r\\n\", \"UANGEMAS/UE_7G_3.webp\\r\\n\"]', 0, '2025-09-12 09:12:07', 'https://indracostore.com/product/Uang-Emas-Kopi-Special-1-sacehts-x-7g', 'Uang-Emas-Kopi-Special-1-sacehts-x-7g', 'https://shopee.co.id/product/283021328/25461956407/', 'https://www.blibli.com/p/uang-emas-kopi-special-10-sachets-x-7g/ps--INT-60044-00153', 'inactive', 0, '2026-03-17 15:07:41', '2026-04-24 08:46:44');
INSERT INTO `master_produk` VALUES (193, 7, 6, NULL, NULL, NULL, 'UCAFE Instant Coffeemix 2 in 1 Coffee & Creamer No Sugar Added', 'ucafe-instant-coffeemix-2-in-1-coffee-creamer-no-sugar-added-uccc15', 'UCCC15', 'UCAFÉ Coffee & Creamer, NO SUGAR ADDED!\r\nSensasi instant coffee mix 2in1 kopi dan krimer, buat kamu yang menikmati kopi tanpa gula. Keseimbangan rasa yang pas untuk apapun aktivitasmu. #DiscoverTheTrueU', 'UCAFÉ Coffee & Creamer, NO SUGAR ADDED!\r\nSensasi instant coffee mix 2in1 kopi dan krimer, buat kamu yang menikmati kopi tanpa gula. Keseimbangan rasa yang pas untuk apapun aktivitasmu. #DiscoverTheTrueU', 'Renceng', '15 sachets x 12g', 31300.00, 'images/uploads/1774419806_p_ucafe-instant-coffeemix-2-in-1-coffee-creamer-no-sugar-added-uccc15.png', '[\"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - 2IN1 - B.webp\", \"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - 2IN1 - F - 2.webp\", \"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - 2IN1 - F - 3.webp\"]', 0, '2026-01-29 18:24:58', NULL, 'UCAFE-Instant-Coffeemix-2-in-1-Coffee-&-Creamer-No-Sugar-Added-15-sachets-x-12g', 'https://shopee.co.id/product/283021328/24672409643/', 'https://www.blibli.com/p/ucafe-instant-coffeemix-2-in-1-coffee-creamer-15-sachets-x-12g/ps--INT-60044-00155', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:22');
INSERT INTO `master_produk` VALUES (194, 7, 6, NULL, NULL, NULL, 'UCAFE Instant Coffeemix Cappuccino No Sugar Added', 'ucafe-instant-coffeemix-cappuccino-no-sugar-added-uccns15', 'UCCNS15', 'UCAFÉ Cappuccino NO SUGAR ADDED! <br>Untuk kamu si unik dan penikmat kopi tanpa gula.<br>Rasakan sensasi Cappuccino asli dalam instant coffee mix yang selalu pas untuk #DiscoverTheTrueU!', 'UCAFÉ Cappuccino NO SUGAR ADDED! <br>Untuk kamu si unik dan penikmat kopi tanpa gula.<br>Rasakan sensasi Cappuccino asli dalam instant coffee mix yang selalu pas untuk #DiscoverTheTrueU!', 'Renceng', '15 sachets x 12g', 38500.00, 'images/uploads/1774419845_p_ucafe-instant-coffeemix-cappuccino-no-sugar-added-uccns15.png', '[\"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - CAP - B.webp\", \"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - CAP - F - 2.webp\", \"UCAFE/INDRACOSTORE IP - SUPRESSO UCAFE - CAP - F - 3.webp\"]', 0, '2026-01-29 18:24:36', NULL, 'UCAFE-Instant-Coffeemix-Cappuccino-No-Sugar-Added-15-sachets-x-12g', 'https://shopee.co.id/product/283021328/25422406718/', 'https://www.blibli.com/p/ucafe-instant-coffeemix-cappuccino-no-sugar-added-15-sachets-x-12g/ps--INT-60044-00154', 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:22');
INSERT INTO `master_produk` VALUES (195, 8, 4, NULL, NULL, NULL, 'Supresso Single Origin Assorted Coffee Capsules', 'supresso-single-origin-assorted-coffee-capsules-supas15c', 'SUPAS15C', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form. Experience Indonesian coffee in its purest form, with Supresso.\r\n \r\n \r\nTraveling around Indonesia with us has been made easier with our One-Stop-Capsules with ten Single Origin Coffee Variants together in a box! Happy exploring.', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form. Experience Indonesian coffee in its purest form, with Supresso.\r\n \r\n \r\nTraveling around Indonesia with us has been made easier with our One-Stop-Capsules with ten Single Origin Coffee Variants together in a box! Happy exploring.', 'Box', '10 Capsules x 6g', 105300.00, 'SUPRESSO/photo_2024-09-01_11-27-41.jpg', '[\"SUPRESSO/photo_2024-09-01_11-27-36.jpg\", \"SUPRESSO/photo_2024-09-01_11-27-45.jpg\"]', 0, '2025-02-21 10:53:38', NULL, 'supresso-single-origin-assorted-coffee-capsules-10-capsules-x-6g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-26 09:40:22');
INSERT INTO `master_produk` VALUES (196, 1, 8, NULL, NULL, NULL, 'Tugu Buaya Kopi Special', 'tugu-buaya-kopi-special-tbs350', 'TBS350', 'Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Biji kopi kualitas terbaik yang dibutuhkan untuk diolah menggunakan mesin modern dan melalui proses higienis menghasilkan kopi bubuk dengan cita rasa yang luar biasa.', 'Bag', '1 Bag x 350g', 42800.00, 'images/uploads/1774411796_p_tugu-buaya-kopi-special-tbs350.png', '[\"TUGUBUAYA/TB_380G_2.webp\", \"TUGUBUAYA/TB_380G_3.webp\"]', 0, '2025-01-13 11:30:01', 'https://indracostore.com/product/Tugu-Buaya-Kopi-Special-1-Bag-x-350g', 'Tugu-Buaya-Kopi-Special-1-Bag-x-350g', 'https://shopee.co.id/product/283021328/25461940225/', 'https://www.blibli.com/p/tugu-buaya-kopi-special-380g/ps--INT-60044-00151', 'active', 0, '2026-03-17 15:07:41', '2026-03-25 13:38:07');
INSERT INTO `master_produk` VALUES (197, 8, 4, NULL, NULL, NULL, 'Supresso Single Origin Assorted Drip Coffee', 'supresso-single-origin-assorted-drip-coffee-supas10d', 'SUPAS10D', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form.', 'With coffee beans sourced from the East to the West of Indonesia, Supresso\'s collection of Indonesian single-origin coffee results in a premium range of exquisite and distinctive tastes profile. We whole-heartedly devote our premium and supreme quality coffee to all ardent coffee lovers worldwide, in beans, ground, drip, and capsule form. \r\n\r\nExperience Indonesian coffee in its purest form, with Supresso.\r\n\r\nTraveling around Indonesia with us has been made easier with Single Origin Coffee Variants together in a box! Happy exploring.\r\n\r\n1x Aceh Gayo | 1x Peaberry | 1x Sumatra Madheling | 1x Lampung | 1x Manglayang | 1x West Java | 1x Java | 1x Bali Kintamani | 1x Flores Bajawa | 1x Toraja Kalosi', 'Drip', '10g x 10 Coffee Drip', 125550.00, 'SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip_1.webp', '[\"SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip2.webp\", \"SUPRESSO/251118_supresso_indraco_web_marketplace_bundle_mix_drip3.webp\"]', 0, '2025-11-24 11:19:40', NULL, 'supresso-single-origin-assorted-drip-coffee-10g-x-10-coffee-drip', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-17 15:07:41');
INSERT INTO `master_produk` VALUES (198, 12, 14, NULL, NULL, NULL, 'Ceria Kopi Bubuk Halus 1500g', 'ceria-kopi-bubuk-halus-1500g-cr1500', 'CR1500', 'Kopi hitam dengan aroma harum dan rasa yang mantap. Diolah dan diracik untuk menghasilkan rasa kopi hitam kesukaan semua!', 'PRODUK BARU!<br>\r\nKopi Ceria - Kopi Hitam Bubuk 1500g<br><br>\r\n\r\nKopi hitam dengan aroma harum dan rasa yang mantap. Diolah dan diracik untuk menghasilkan rasa kopi hitam kesukaan semua!<br><br>\r\n\r\nSangat cocok untuk warung kopi, kafe, restoran, atau bakery.<br><br>\r\n\r\nSaran Penyajian:<br><br>\r\n\r\n- Masukkan kopi Ceria secukupnya ke dalam cangkir dan tambahkan gula sesuai selera.<br>\r\n- Tuangkan air panas ±200 ml, aduk rata dan kopi siap dinikmati.', 'Bag', '1 Bag x 1500g', 42187.00, 'CERIA/240429 - -KOPI-CERIA - -E-COMMERCE - BARU.png', '[\"CERIA/240429 - KOPI CERIA - E COMMERCESlide 2 (1).jpg\", \"CERIA/240429 - KOPI CERIA - E COMMERCESlide 3 (1).jpg\"]', 0, '2025-11-17 10:33:08', NULL, 'ceria-kopi-bubuk-halus-1500g-1-bag-x-1500g', NULL, NULL, 'inactive', 0, '2026-03-17 15:07:41', '2026-03-17 15:07:41');
