INSERT INTO `master_variant` VALUES (1, 2, 'Signature Blend', 'Signature-Blend', '100% Arabica. Pure 100% Arabica coffee beans originating from various regions in Indonesia, and roasted with the Full City Roast mode. Relish in unmatched acidity along with hints of warm spices, tropical fruits and chocolaty caramel nuances.', 'Tropical Fruity - Warm Spices - Choco Caramel Nuances', 3.0, 3.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Signature-Blend_map_1774494550.png', 0.45, 'images/uploads/variant/Signature-Blend_icon_1774424500.png', '#797a7d', '#ffffff', 'active', NULL, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (2, 2, 'Espresso Blend', 'Espresso-Blend', '70% Arabica - 30% Robusta. A 70/30 blend of Arabica and Robusta beans originating from the vast regions of Indonesia and roasted with the Full City Roast mode. Experience the dark chocolate hints alongside caramel and romantic florals of this one of a kind blend with medium acidity and heavy body.', 'Dark Chocolate - Caramel - Romantic Florals', 3.0, 4.0, 'Full City Roast', '70% Arabica & 30% Robusta Coffee', 'images/uploads/variant/Espresso-Blend_map_1774494537.png', 0.45, 'images/uploads/variant/Espresso-Blend_icon_1774424534.png', '#24a8a3', '#ffffff', 'active', NULL, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (3, 2, 'Equilibre Blend', 'Equilibre-Blend', '50% Arabica - 50% Robusta. A 50/50 blend of Arabica and Robusta beans made with coffee grown and farmed in Indonesia and roasted with the City+ Roast mode. With a lower acidity compared to our Signature and Espresso blends, Equilibre is a balanced blend which possesses good body alongside sweet fruity and floral aftertastes with nutty and warm spice nuances.', 'Sweet Fruity Floral Aftertaste - Nutty Warm Spice Nuances', 2.0, 3.0, 'City+ Roast', '50% Arabica & 50% Robusta Coffee', 'images/uploads/variant/Equilibre-Blend_map_1774494524.png', 0.45, 'images/uploads/variant/Equilibre-Blend_icon_1774424556.png', '#7b7727', '#ffffff', 'active', NULL, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (4, 2, 'Lumiere Blend', 'Lumiere-Blend', '30% Arabica - 70% Robusta. A 30/70 blend of Arabica and Robusta beans originating from the different regions of Indonesia and roasted with the City+ Roast mode. Taste the complementary sweet chocolaty hints, warm spices and slight earthiness amongst the caramel chocolaty undertones, with lower acidity and strong body.', 'Sweet Chocolaty & Warm Spices - Slight Earthy - Caramel Chocolaty Undertones', 1.0, 4.5, 'City+ Roast', '30% Arabica Coffee & 70% Robusta', 'images/uploads/variant/Lumiere-Blend_map_1774494510.png', 0.45, 'images/uploads/variant/Lumiere-Blend_icon_1774424575.png', '#837bfa', '#ffffff', 'active', NULL, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (5, 2, 'Exotic Blend', 'Exotic-Blend', '20% Arabica - 80% Robusta. An 20/80 blend of Arabica and Robusta roasted with the City+ Roast mode and consisting of only Indonesian beans. Its lowest acidity amongst our Gourmet Collection and high bitterness characterise this blend, with sweet chocolaty aftertastes and woody, nuttiness in its undertones.', 'Sweet Chocolaty Aftertaste - Woody - Nutty - Chocolaty Undertones', 1.0, 4.0, 'City+ Roast', '20% Arabica Coffee & 80% Robusta', 'images/uploads/variant/Exotic-Blend_map_1774494497.png', 0.45, 'images/uploads/variant/Exotic-Blend_icon_1774424597.png', '#ac1239', '#ffffff', 'active', NULL, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (6, 2, 'Ombre Blend', 'Ombre-Blend', '100% Robusta. A robusta blend consisting of only Indonesian beans roasted to Full City roast. Characterised with no acidity and a strong body, rich choco caramel aftertastes and woody nuttiness in its undertones complete this blend.', 'Rich Choco Caramel - Nutty - Spicy - Sweet Chocolaty', 0.0, 5.0, 'Full City Roast', '100% Robusta Coffee', 'images/uploads/variant/Ombre-Blend_map_1774494485.png', 0.45, 'images/uploads/variant/Ombre-Blend_icon_1774424624.png', '#483749', '#ffffff', 'active', 0, '2026-03-17 16:13:20', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (7, 2, 'Décaféiné Blend', 'Decafeine-Blend', 'Teeming with exceptional fragrances alongside hints of caramel and spices, this dark roast coffee is smooth and medium-bodied with delicate acidity, all wrapped in a decaffeinated package.', 'Boldly Roasted - Notes of Caramel & Spices - Delicate Acidity', 0.5, 3.0, 'Dark Roast', '100% Arabica Coffee', 'images/uploads/variant/Decafeine-Blend_map_1774494473.png', 0.45, 'images/uploads/variant/Decafeine-Blend_icon_1774424643.png', '#345461', '#ffffff', 'active', 0, '2026-03-17 16:14:18', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (8, 1, 'Аceh Gayo', 'Асеh-Gayo', 'Aceh Gayo coffee is often used in most coffee shops commonly for cafe latte. It has light earthy notes with a mild body and bittersweet spicy chocolate taste. Soft in acidity, this coffee reveals some elegant caramel-fruity flavours, marrying a perfect combination of spicy and sweet. Its unique taste will make you crave for more.', 'Spicy - Caramel & Chocolaty - Fruity - Slightly Earthy Note', 3.0, 2.5, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Асен-Gayo_map_1774514521.png', 0.45, 'images/uploads/variant/Асен-Gayo_icon_1774403746.png', '#00a5cd', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (9, 1, 'Sumatra Mandheling', 'Sumatra-Mandheling', 'These Arabica coffee beans are not only rare and rich in history but also one of the highly recognised by gourmet coffee producers in the world. The syrupy, full body of Sumatra Mandheling, combined with its muted acidity, makes an elegant, smooth cup of coffee. A blend of sweet and spicy, exuding an exotic flavour.', 'Floral & Fruity - Sweet & Spicy - Slightly Earthy Undertones', 4.0, 3.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Sumatra-Mandheling_map_1774514578.png', 0.45, 'images/uploads/variant/Sumatra-Mandheling_icon_1773888433.png', '#d2441e', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (10, 1, 'Lampung', 'Lampung', 'Well-sought after by the worlds coffee industry, this Robusta coffee gives off an immense strong-bodied bitter taste with the essence of chocolate, slightly earthy aroma and tobacco undertones. The absence of acidity is Lampungs trademark.', 'Chocolaty - Slightly Earthy - Tobacco Notes', 0.0, 5.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Lampung_map_1774514589.png', 0.45, 'images/uploads/variant/Lampung_icon_1773888420.png', '#e54078', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (11, 1, 'Manglayang', 'Manglayang', 'Famous for its traditional coffee cultivation that retains its original character and distinctive flavours, our Manglayang Arabica coffee provides a smooth, medium body. The gentle plum acidity flavour it exudes, complements its sweet maple syrup notes, leaving a fruity lingering mouthfeel.', 'Sweet Maple Syrup - Fruity - Acidic Plum', 2.5, 3.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Manglayang_map_1774514602.png', 0.45, 'images/uploads/variant/Manglayang_icon_1773888408.png', '#ff595b', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (12, 1, 'West Java', 'West-Java', 'West Java coffees sour flavour is not too dominant yet not too earthy. They have a berry-like, wine taste with a sweet honey aroma that taste great on their own or paired well with dark chocolate desserts that accentuates its flavour. To bring out its earthiness, enjoy it with a hearty brunch made with cheese, mushrooms or bacon.', 'Wine Taste - Berry Like - Sweet Hone', 0.0, 4.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/West-Java_map_1774514613.png', 0.45, 'images/uploads/variant/West-Java_icon_1773888398.png', '#046240', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (13, 1, 'Java', 'Java', 'Supresso Java Robusta coffee beans are thoroughly wet-processed, kicking off the acidity, drops the body and reduces the earthiness of the cup to a unique sweetness. Its strong malty taste with hints of tobacco notes will give a perfect combination when added with cocoa - great for brewing your delicious mocha.', 'Sweetness - Strong Malty - Tobacco Notes', 0.0, 3.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Java_map_1774514624.png', 0.45, 'images/uploads/variant/Java_icon_1773888332.png', '#80bc04', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (14, 1, 'Bali Kintamani', 'Bali-Kintamani', 'Grown in the highlands of Kintamani, this coffee has unique characteristics derived from wet processing method, making them slightly sweeter. The mild body of the coffee exudes a clean light and refreshing taste exhibiting a citrusy, fruity finish. It is a must-try for those who do not like the bitter taste.', 'Good Balance - Herbal & Nutty - Lively Acidity - Sweet Citrus Notes', 3.0, 2.5, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Bali-Kintamani_map_1774514637.png', 0.45, 'images/uploads/variant/Bali-Kintamani_icon_1773888324.png', '#e90b2a', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (15, 1, 'Flores Bajawa', 'Flores-Bajawa', 'Aceh Gayo coffee is often used in most coffee shops commonly for cafe latte. It has light earthy notes with a mild body and bittersweet spicy chocolate taste. Soft in acidity, this coffee reveals some elegant caramel-fruity flavours, marrying a perfect combination of spicy and sweet. Its unique taste will make you crave for more.', 'Chocolate Fudges - Floral Nectareous Sweetness - Vanilla Hints - Caramel Undertones', 2.0, 4.0, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Flores-Bajawa_map_1774518242.png', 0.45, 'images/uploads/variant/Flores-Bajawa_icon_1773888310.png', '#d939b3', '#ffffff', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
INSERT INTO `master_variant` VALUES (16, 1, 'Toraja Kalosi', 'Toraja-Kalosi', 'Our Supresso Toraja Kalosi is highly valued among Japans coffee drinkers because of its quality traditional processing, offering multiple layers of flavours that reveal something upon each sip. The heavy-bodied coffee is low in acidity, and its delicate aroma denotes warm spices with a sweet and smooth aftertaste.', 'Warm Spices - Sweet & Smooth Aftertastes', 2.0, 3.5, 'Full City Roast', '100% Arabica Coffee', 'images/uploads/variant/Toraja-Kalosi_map_1774518232.png', 0.50, 'images/uploads/variant/Toraja-Kalosi_icon_1773888029.png', '#facd00', '#000000', 'active', NULL, '2026-03-17 16:14:48', NULL, NULL, NULL);
